package com.treerunning;

import com.treerunning.data.CropType;

/**
 * The dropdown choices shown in the plugin settings, one enum per patch type.
 */
public final class CropChoices
{
	private CropChoices()
	{
	}

	public enum Tree
	{
		OAK(CropType.OAK),
		WILLOW(CropType.WILLOW),
		MAPLE(CropType.MAPLE),
		YEW(CropType.YEW),
		MAGIC(CropType.MAGIC);

		private final CropType crop;

		Tree(CropType crop)
		{
			this.crop = crop;
		}

		public CropType crop()
		{
			return crop;
		}

		@Override
		public String toString()
		{
			return crop.getDisplayName();
		}
	}

	public enum Fruit
	{
		APPLE(CropType.APPLE),
		BANANA(CropType.BANANA),
		ORANGE(CropType.ORANGE),
		CURRY(CropType.CURRY),
		PINEAPPLE(CropType.PINEAPPLE),
		PAPAYA(CropType.PAPAYA),
		PALM(CropType.PALM),
		DRAGONFRUIT(CropType.DRAGONFRUIT);

		private final CropType crop;

		Fruit(CropType crop)
		{
			this.crop = crop;
		}

		public CropType crop()
		{
			return crop;
		}

		@Override
		public String toString()
		{
			return crop.getDisplayName();
		}
	}

	public enum Hardwood
	{
		TEAK(CropType.TEAK),
		MAHOGANY(CropType.MAHOGANY),
		CAMPHOR(CropType.CAMPHOR),
		IRONWOOD(CropType.IRONWOOD),
		ROSEWOOD(CropType.ROSEWOOD);

		private final CropType crop;

		Hardwood(CropType crop)
		{
			this.crop = crop;
		}

		public CropType crop()
		{
			return crop;
		}

		@Override
		public String toString()
		{
			return crop.getDisplayName();
		}
	}
}

package com.treerunning;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Writes what the tracker sees (Farming XP drops, patch changes, saplings leaving the
 * inventory, and what it decided) to RuneLite's own log, .runelite/logs/client.log, so a run
 * can be checked afterwards. Off unless turned on in settings. Every line starts with
 * "[Tree Running]" so it's easy to find.
 */
final class DebugLog
{
	private static final Logger LOG = LoggerFactory.getLogger("TreeRunning");

	private volatile boolean enabled;

	void setEnabled(boolean enabled)
	{
		boolean was = this.enabled;
		this.enabled = enabled;
		if (enabled && !was)
		{
			log(-1, "--- debug log on ---");
		}
	}

	boolean isEnabled()
	{
		return enabled;
	}

	/** @param tick the game tick, or -1 if not in game */
	void log(int tick, String message)
	{
		if (enabled)
		{
			LOG.info("[Tree Running] t{}  {}", tick, message);
		}
	}

	void shutDown()
	{
		enabled = false;
	}
}

package com.treerunning;

import com.treerunning.core.HerbPlanner;
import com.treerunning.core.HerbTask;
import com.treerunning.core.InventoryFit;
import com.treerunning.core.Route;
import com.treerunning.core.RouteItem;
import com.treerunning.core.RunNeeds;
import com.treerunning.core.RunRecord;
import com.treerunning.core.RunTask;
import com.treerunning.core.SeenPatch;
import com.treerunning.core.SupplyCalculator;
import com.treerunning.data.Compost;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.RouteStep;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * A snapshot of everything the side panel and overlays show. Built on the client thread and
 * never changed after it's published, so the Swing and render threads can read it safely.
 */
final class PanelData
{
	static final PanelData EMPTY = new PanelData();

	boolean loggedIn;
	int currentXp;
	int level;

	TreeRunningConfig.GoalType goalType = TreeRunningConfig.GoalType.LEVEL;
	int goalLevel = 99;
	int goalXp;

	double plannedXpPerRun;
	int plannedRuns = -1;
	double actualXpPerRun;
	int actualRunsCounted;
	/** Tree runs to the goal, or -1 if the plan can't reach it. */
	int runsLeft = -1;
	boolean runsLeftFromActual;
	int runsPerDay = 1;

	// Tree run
	List<RunTask> tasks = Collections.emptyList();
	List<RouteItem> items = Collections.emptyList();
	Set<String> done = Collections.emptySet();
	boolean runActive;
	long runStartedAt;
	int runXpSoFar;
	String lastMatch;
	List<RunNeeds.Line> needs = Collections.emptyList();
	/** Inventory slots the rest of the run needs, and the first stretch that won't fit (or null). */
	int slots;
	InventoryFit.Overflow overflow;
	/** What each patch looked like when last seen, by key. */
	Map<String, SeenPatch> seen = Collections.emptyMap();
	Set<String> paid = Collections.emptySet();
	/** Ticked patches whose gardener hasn't been paid. */
	Set<String> unpaid = Collections.emptySet();
	/** Planted allotments whose gardener hasn't been paid (when paying is on). */
	Set<String> unpaidAllotments = Collections.emptySet();
	/** When each tree patch was planted on a finished run, by key. */
	Map<String, Long> plantedAt = Collections.emptyMap();
	boolean highlightGardeners = true;
	/** Grown herb patches next to tree-run stops ("herbs on the way"); empty when that's off. */
	Map<RouteStep, List<HerbTask>> onTheWay = Collections.emptyMap();

	List<SupplyCalculator.SupplyLine> supplies = Collections.emptyList();
	long bankSeenAt;
	long vaultSeenAt;
	List<RunRecord> runs = Collections.emptyList();
	Map<RouteStep, String> travel = Collections.emptyMap();
	Map<HerbLocation, String> herbTravel = Collections.emptyMap();
	TreeRunningConfig.BankFilter bankFilter = TreeRunningConfig.BankFilter.OFF;
	/** Changes when the bank filter's items change. */
	int tagKey;

	// Herb run
	List<HerbTask> herbTasks = Collections.emptyList();
	Set<String> herbDone = Collections.emptySet();
	boolean herbActive;
	long herbStartedAt;
	List<HerbPlanner.Need> herbNeeds = Collections.emptyList();
	Compost compost = Compost.BOTTOMLESS;
	boolean compostCarried = true;
	boolean secateursExpected;
	boolean secateursCarried;
	int herbPicked;
	long herbValue;
	long herbCost;
	long herbSeedCost;
	long herbCompostCost;
	/** Seeds planted this herb run: name → count. */
	Map<String, Integer> herbSeeds = Collections.emptyMap();
	boolean countSeeds = true;
	int herbXp;
	List<RunRecord> herbRuns = Collections.emptyList();
	String herbLastMatch;
	List<HerbPlanner.Estimate> picker = Collections.emptyList();
	/** Estimated profit per herb patch, by key. */
	Map<String, Long> herbEstimates = Collections.emptyMap();
	double herbXpPerRun;
	int herbRunsPerDay;

	// Profit
	long lifetimeTreeProfit;
	long lifetimeHerbProfit;
	RunRecord lastTreeRun;
	RunRecord lastHerbRun;

	int xpRemaining()
	{
		return Math.max(0, goalXp - currentXp);
	}

	int dueCount()
	{
		int n = 0;
		for (RunTask t : tasks)
		{
			if (t.isDue())
			{
				n++;
			}
		}
		return n;
	}

	int doneCount()
	{
		int n = 0;
		for (RunTask t : tasks)
		{
			if (t.isDue() && done.contains(t.getKey()))
			{
				n++;
			}
		}
		return n;
	}

	RouteItem nextItem()
	{
		return Route.next(items, done);
	}

	String travelNote(RouteStep step)
	{
		String note = travel.get(step);
		return note != null ? note : step.getTravel();
	}

	String travelNote(HerbLocation location)
	{
		String note = herbTravel.get(location);
		return note != null ? note : location.getTravel();
	}

	/** Days to the goal with tree and herb runs together, or -1. */
	int daysLeft()
	{
		double treePerRun = actualXpPerRun > 0 ? actualXpPerRun : plannedXpPerRun;
		double perDay = treePerRun * runsPerDay + herbXpPerRun * herbRunsPerDay;
		if (perDay <= 0)
		{
			return -1;
		}
		return (int) Math.ceil(xpRemaining() / perDay);
	}

	int herbDueCount()
	{
		int n = 0;
		for (HerbTask t : herbTasks)
		{
			if (t.isDue())
			{
				n++;
			}
		}
		return n;
	}

	int herbPlantedCount()
	{
		int n = 0;
		for (HerbTask t : herbTasks)
		{
			if (t.isDue() && t.isDone(herbDone, HerbTask.PLANT))
			{
				n++;
			}
		}
		return n;
	}
}

package com.treerunning;

import com.treerunning.core.HerbTask;
import com.treerunning.core.RouteItem;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines in the game world: the next tree patch brightly, other due tree patches and
 * herb patches more faintly, and the gardener of a patch you've planted but not paid.
 */
class PatchHighlightOverlay extends Overlay
{
	private static final Color NEXT = new Color(0x6C, 0xC2, 0x4A);
	private static final Color OTHER = new Color(0xE0, 0xC0, 0x40, 0x90);
	private static final Color HERB = new Color(0x8F, 0xD1, 0x6A, 0xC0);
	private static final Color PAY = new Color(0xFF, 0x98, 0x1F);

	private final TreeRunningPlugin plugin;
	private final ModelOutlineRenderer outlines;

	@Inject
	PatchHighlightOverlay(TreeRunningPlugin plugin, ModelOutlineRenderer outlines)
	{
		this.plugin = plugin;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		PanelData d = plugin.getData();
		if (!d.loggedIn)
		{
			return null;
		}
		Map<String, GameObject> objects = plugin.getPatchObjects();
		if (plugin.getConfig().highlightPatches())
		{
			RouteItem next = d.nextItem();
			String nextKey = next != null && !next.isBank() ? next.getKey() : null;
			for (RouteItem item : d.items)
			{
				if (item.isBank() || !item.isDue() || d.done.contains(item.getKey()))
				{
					continue;
				}
				GameObject object = objects.get(item.getKey());
				if (object != null)
				{
					boolean isNext = item.getKey().equals(nextKey);
					outlines.drawOutline(object, isNext ? 3 : 2, isNext ? NEXT : OTHER, isNext ? 4 : 2);
				}
			}
			for (HerbTask task : d.herbTasks)
			{
				if (!task.isDue())
				{
					continue;
				}
				for (String patch : task.getPatchKeys())
				{
					GameObject object = objects.get(patch);
					if (object != null && !d.herbDone.contains(HerbTask.stepKey(patch, HerbTask.PLANT)))
					{
						outlines.drawOutline(object, 2, HERB, 2);
					}
				}
			}
		}
		if (d.highlightGardeners && (!d.unpaid.isEmpty() || !d.unpaidAllotments.isEmpty()))
		{
			Map<Integer, NPC> gardeners = plugin.getGardeners();
			java.util.Set<String> keys = new java.util.HashSet<>(d.unpaid);
			keys.addAll(d.unpaidAllotments);
			for (String key : keys)
			{
				TrackedPatch patch = TrackedPatch.BY_KEY.get(key);
				NPC npc = patch == null ? null : gardeners.get(patch.gardener);
				if (npc != null)
				{
					outlines.drawOutline(npc, 2, PAY, 3);
				}
			}
		}
		return null;
	}
}

package com.treerunning;

import com.treerunning.core.RunRecord;
import com.treerunning.core.SeenPatch;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything the plugin remembers per account. Saved as JSON in the RuneScape profile
 * config, so each of your accounts has its own progress.
 */
class RunState
{
	/** More than any real run could reach; history entries beyond these are errors. */
	static final int MAX_HERB_RUN_PICKS = 1_000;
	static final int MAX_HERB_RUN_XP = 200_000;
	static final int MAX_TREE_RUN_XP = 1_000_000;

	/** True from the first patch of a run until you press Finish run. */
	boolean active;
	/** Farming XP at the start of the current run. */
	int startXp;
	long startedAt;
	/** Patches and bank stops ticked on the current run. */
	Set<String> done = new HashSet<>();
	/** When each patch was ticked on the current run. Growth timers start from these on Finish run. */
	Map<String, Long> tickedAt = new HashMap<>();
	/** When the last patch of the current run was ticked. */
	long lastTickAt;
	/** Farming XP shortly after the last patch (covers planting and payments after a check-health). */
	int runLastXp;
	/** When long-growing patches (hardwood, redwood, Hespori) were last planted, from finished runs. */
	Map<String, Long> plantedAt = new HashMap<>();
	/** Finished runs, oldest first. */
	List<RunRecord> runs = new ArrayList<>();
	/** XP of finished runs saved by older versions. Moved into runs on load. */
	List<Integer> runXp;
	/** Bank contents of tracked items (unnoted item ID → quantity) from the last time you opened it. */
	Map<Integer, Integer> bank = new HashMap<>();
	long bankSeenAt;
	/** Farming Guild seed vault contents, from the last time you opened it. */
	Map<Integer, Integer> vault = new HashMap<>();
	long vaultSeenAt;

	/** What each patch (tree, herb or allotment) looked like when last seen, by patch key. */
	Map<String, SeenPatch> seen = new HashMap<>();
	/** Patches whose gardener was paid on the current tree or herb run. */
	Set<String> paid = new HashSet<>();
	/** Produce picked on the current tree run (fruit, bark), by item ID. */
	Map<Integer, Integer> treeProduce = new HashMap<>();

	// Herb runs
	boolean herbActive;
	int herbStartXp;
	long herbStartedAt;
	long herbLastTickAt;
	/** Steps done on the current herb run ("herb:FALADOR|plant"). */
	Set<String> herbDone = new HashSet<>();
	int herbPicked;
	long herbValue;
	long herbCost;
	long herbSeedCost;
	long herbCompostCost;
	/** Seeds planted on the current herb run, by name. */
	Map<String, Integer> herbSeeds = new java.util.LinkedHashMap<>();
	int herbXp;
	List<RunRecord> herbRuns = new ArrayList<>();
	/** The "all grown" time already notified about, so it's only sent once. */
	long herbNotifiedFor;

	/** Gson leaves missing fields null when loading older saves. */
	void fillDefaults()
	{
		if (done == null)
		{
			done = new HashSet<>();
		}
		if (plantedAt == null)
		{
			plantedAt = new HashMap<>();
		}
		if (tickedAt == null)
		{
			tickedAt = new HashMap<>();
		}
		if (runs == null)
		{
			runs = new ArrayList<>();
		}
		if (runXp != null)
		{
			for (Integer xp : runXp)
			{
				if (xp != null)
				{
					runs.add(new RunRecord(0, xp, -1));
				}
			}
			runXp = null;
		}
		if (seen == null)
		{
			seen = new HashMap<>();
		}
		if (paid == null)
		{
			paid = new HashSet<>();
		}
		if (treeProduce == null)
		{
			treeProduce = new HashMap<>();
		}
		if (herbDone == null)
		{
			herbDone = new HashSet<>();
		}
		if (herbRuns == null)
		{
			herbRuns = new ArrayList<>();
		}
		if (herbSeeds == null)
		{
			herbSeeds = new java.util.LinkedHashMap<>();
		}
		// Runs saved by a version that read all your XP at login as one action: no run picks
		// thousands of herbs or gains this much XP.
		herbRuns.removeIf(r -> r == null || r.picked > MAX_HERB_RUN_PICKS || r.xp > MAX_HERB_RUN_XP);
		runs.removeIf(r -> r == null || r.xp > MAX_TREE_RUN_XP);
		if (bank == null)
		{
			bank = new HashMap<>();
		}
		if (vault == null)
		{
			vault = new HashMap<>();
		}
	}
}

package com.treerunning;

import com.treerunning.core.HerbTask;
import com.treerunning.core.RunTask;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.PatchKind;
import com.treerunning.data.PatchLocation;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Every patch the plugin reads in game: the tree patches, herb patches and allotments.
 * Each has a key (the same as its run task's), the varbit holding its state, how to read
 * that varbit, and where the varbit is sent.
 */
final class TrackedPatch
{
	enum Type
	{
		TREE,
		HERB,
		ALLOTMENT
	}

	final String key;
	final Type type;
	final PatchKind kind;
	final int varbit;
	/** The tree patch, or null. */
	final PatchLocation tree;
	/** The herb location (herb patch or allotment), or null. */
	final HerbLocation herb;
	/** Which allotment, or -1. */
	final int allotment;
	/** The gardener who protects it, or -1. */
	final int gardener;
	/** The option for this patch in the gardener's "which patch?" dialogue, or -1 if there's only one. */
	final int gardenerOption;

	private TrackedPatch(String key, Type type, PatchKind kind, int varbit, PatchLocation tree, HerbLocation herb, int allotment,
		int gardener, int gardenerOption)
	{
		this.key = key;
		this.type = type;
		this.kind = kind;
		this.varbit = varbit;
		this.tree = tree;
		this.herb = herb;
		this.allotment = allotment;
		this.gardener = gardener;
		this.gardenerOption = gardenerOption;
	}

	boolean isAt(int x, int y, int plane)
	{
		return tree != null ? tree.isAt(x, y, plane) : herb.isAt(x, y, plane);
	}

	String name()
	{
		if (tree != null)
		{
			return tree.getDisplayName();
		}
		return herb.getDisplayName() + (allotment < 0 ? " herb patch" : " " + herb.allotmentName(allotment).toLowerCase());
	}

	static final List<TrackedPatch> ALL;
	static final Map<String, TrackedPatch> BY_KEY;
	static final Map<Integer, List<TrackedPatch>> BY_VARBIT;

	static
	{
		List<TrackedPatch> all = new ArrayList<>();
		for (PatchLocation location : PatchLocation.values())
		{
			all.add(new TrackedPatch(RunTask.keyFor(location, 0), Type.TREE, location.getKind(), location.getVarbit(), location,
				null, -1, location.getGardener(), -1));
		}
		for (HerbLocation location : HerbLocation.values())
		{
			all.add(new TrackedPatch(HerbTask.keyFor(location, -1), Type.HERB, PatchKind.HERB, location.getHerbVarbit(), null,
				location, -1, -1, -1));
			int[] varbits = location.getAllotmentVarbits();
			for (int i = 0; i < varbits.length; i++)
			{
				all.add(new TrackedPatch(HerbTask.keyFor(location, i), Type.ALLOTMENT, PatchKind.ALLOTMENT, varbits[i], null,
					location, i, location.getAllotmentGardener(), varbits.length > 1 ? location.getAllotmentOption(i) : -1));
			}
		}
		Map<String, TrackedPatch> byKey = new HashMap<>();
		Map<Integer, List<TrackedPatch>> byVarbit = new HashMap<>();
		for (TrackedPatch p : all)
		{
			byKey.put(p.key, p);
			byVarbit.computeIfAbsent(p.varbit, v -> new ArrayList<>()).add(p);
		}
		ALL = Collections.unmodifiableList(all);
		BY_KEY = Collections.unmodifiableMap(byKey);
		BY_VARBIT = Collections.unmodifiableMap(byVarbit);
	}
}

package com.treerunning;

import com.treerunning.data.AllotmentType;
import com.treerunning.data.Compost;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.HerbType;
import com.treerunning.data.PatchLocation;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Plugin settings, shown in RuneLite's configuration panel. The route editor (stop order,
 * travel notes and bank stops) is in the side panel instead, and saves to the hidden keys
 * at the bottom. Key names are kept from earlier versions so saved choices carry over.
 */
@ConfigGroup(TreeRunningConfig.GROUP)
public interface TreeRunningConfig extends Config
{
	String GROUP = "treerunning";

	enum GoalType
	{
		LEVEL("Level"),
		XP("XP");

		private final String label;

		GoalType(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum KandarinDiary
	{
		NONE("None", 0),
		MEDIUM("Medium (+5%)", 0.05),
		HARD("Hard (+10%)", 0.10),
		ELITE("Elite (+15%)", 0.15);

		private final String label;
		private final double bonus;

		KandarinDiary(String label, double bonus)
		{
			this.label = label;
			this.bonus = bonus;
		}

		public double bonus()
		{
			return bonus;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Which run the bank filter shows. Changed from the side panel or the bank. */
	enum BankFilter
	{
		OFF,
		TREE,
		HERB
	}

	/** The settings key for each tree patch's on/off switch. */
	Map<PatchLocation, String> PATCH_KEYS = Keys.patches();
	/** Settings keys for each herb location: on/off, herb, allotments. */
	Map<HerbLocation, String> HERB_ENABLED_KEYS = Keys.herb("herbPatch");
	Map<HerbLocation, String> HERB_CHOICE_KEYS = Keys.herb("herb");
	Map<HerbLocation, String> ALLOTMENT_KEYS = Keys.herb("allotments");

	final class Keys
	{
		private Keys()
		{
		}

		static Map<PatchLocation, String> patches()
		{
			Map<PatchLocation, String> m = new EnumMap<>(PatchLocation.class);
			m.put(PatchLocation.TREE_FARMING_GUILD, "treeFarmingGuild");
			m.put(PatchLocation.TREE_GNOME_STRONGHOLD, "treeGnomeStronghold");
			m.put(PatchLocation.TREE_FALADOR, "treeFalador");
			m.put(PatchLocation.TREE_TAVERLEY, "treeTaverley");
			m.put(PatchLocation.TREE_VARROCK, "treeVarrock");
			m.put(PatchLocation.TREE_LUMBRIDGE, "treeLumbridge");
			m.put(PatchLocation.TREE_NEMUS_RETREAT, "treeNemusRetreat");
			m.put(PatchLocation.FRUIT_FARMING_GUILD, "fruitFarmingGuild");
			m.put(PatchLocation.FRUIT_GNOME_STRONGHOLD, "fruitGnomeStronghold");
