	/** +1.2M, −45k, 950. */
	static String gp(long n)
	{
		String sign = n > 0 ? "+" : n < 0 ? "−" : "";
		return sign + compact(Math.abs(n));
	}

	/** 1h 05m, 12m 30s. */
	static String duration(long ms)
	{
		long s = Math.max(0, ms) / 1000;
		long h = s / 3600;
		long m = (s % 3600) / 60;
		if (h > 0)
		{
			return h + "h " + String.format("%02dm", m);
		}
		return m + "m " + String.format("%02ds", s % 60);
	}

