		c.gridwidth = 3;
		c.weightx = 1;
		box.add(title, c);
		int shortCount = RunNeeds.shortCount(needs);
		JLabel total = small(shortCount > 0 ? shortCount + " short" : RunNeeds.totalSaplings(needs) + " to plant · " + slots + "/28 slots",
			shortCount > 0 ? BAD : MUTED);
