	/** Saves the tree-stop and herb-patch travel notes you typed (both in one setting). */
	void saveTravelNotes(Map<RouteStep, String> notes, Map<HerbLocation, String> herbNotes)
	{
		Map<RouteStep, String> copy = new EnumMap<>(RouteStep.class);
		copy.putAll(notes);
		travelNotes = Collections.unmodifiableMap(copy);
		Map<HerbLocation, String> herbCopy = new EnumMap<>(HerbLocation.class);
		herbCopy.putAll(herbNotes);
		herbTravelNotes = Collections.unmodifiableMap(herbCopy);
		Map<String, String> byName = new HashMap<>();
		for (Map.Entry<RouteStep, String> e : notes.entrySet())
		{
			byName.put(e.getKey().name(), e.getValue());
		}
		for (Map.Entry<HerbLocation, String> e : herbNotes.entrySet())
		{
			byName.put(HERB_TRAVEL_PREFIX + e.getKey().name(), e.getValue());
		}
		setSetting("travelText", gson.toJson(byName));
	}

	private void loadBankStops()
	{
		List<BankStop> loaded = new ArrayList<>();
		try
		{
			List<BankStop> parsed = gson.fromJson(config.bankStops(), new TypeToken<List<BankStop>>()
			{
			}.getType());
			if (parsed != null)
			{
				for (BankStop b : parsed)
				{
					if (b != null && b.id != null && b.getRouteStep() != null)
					{
						loaded.add(b);
					}
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved bank stops", e);
		}
		bankStops = Collections.unmodifiableList(loaded);
	}

	private void loadRouteOrder()
	{
		try
		{
			List<String> stops = gson.fromJson(config.stopOrder(), new TypeToken<List<String>>()
			{
			}.getType());
			Map<String, List<String>> patches = gson.fromJson(config.patchOrder(), new TypeToken<Map<String, List<String>>>()
			{
			}.getType());
			routeOrder = RouteOrder.fromNames(stops, patches);
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved route order", e);
			routeOrder = RouteOrder.defaults();
		}
	}

	private void loadTravelNotes()
	{
		Map<RouteStep, String> notes = new EnumMap<>(RouteStep.class);
		Map<HerbLocation, String> herbNotes = new EnumMap<>(HerbLocation.class);
		try
		{
			Map<String, String> byName = gson.fromJson(config.travelText(), new TypeToken<Map<String, String>>()
			{
			}.getType());
			if (byName != null)
			{
				for (RouteStep step : RouteStep.values())
				{
					String note = byName.get(step.name());
					if (note != null)
					{
						notes.put(step, note);
					}
				}
				for (HerbLocation location : HerbLocation.values())
				{
					String note = byName.get(HERB_TRAVEL_PREFIX + location.name());
					if (note != null)
					{
						herbNotes.put(location, note);
					}
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved travel notes", e);
		}
		travelNotes = Collections.unmodifiableMap(notes);
		herbTravelNotes = Collections.unmodifiableMap(herbNotes);
	}

	// ------------------------------------------------------------------ planning

	private PlanSettings buildSettings()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, config.treeCrop().crop());
		crops.put(PatchType.FRUIT_TREE, config.fruitCrop().crop());
		crops.put(PatchType.HARDWOOD, config.hardwoodCrop().crop());
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		crops.put(PatchType.CRYSTAL, CropType.CRYSTAL);

		Set<PatchLocation> enabled = EnumSet.noneOf(PatchLocation.class);
		for (PatchLocation location : PatchLocation.values())
		{
			if (isPatchEnabled(location))
			{
				enabled.add(location);
			}
		}
		return new PlanSettings(crops, enabled, goalXp(), config.runsPerDay());
	}

	private HerbSettings buildHerbSettings(int level)
	{
		Map<HerbLocation, HerbType> herbs = new EnumMap<>(HerbLocation.class);
		Set<HerbLocation> enabled = EnumSet.noneOf(HerbLocation.class);
		Set<HerbLocation> allotments = EnumSet.noneOf(HerbLocation.class);
		for (HerbLocation location : HerbLocation.values())
		{
			herbs.put(location, herbChoice(location));
			if (isHerbEnabled(location))
			{
				enabled.add(location);
			}
			if (location.getAllotmentCount() > 0 && herbFlag(TreeRunningConfig.ALLOTMENT_KEYS, location, false))
			{
				allotments.add(location);
			}
		}
		double items = (config.magicSecateurs() ? 0.10 : 0) + (config.farmingCape() ? 0.05 : 0);
		return new HerbSettings(herbs, enabled, allotments, config.allotmentCrop(), config.payForAllotments(), config.compost(),
			level, items, config.kandarinDiary().bonus(), config.kourendHard(), !config.ironmanSeeds());
	}

	private int goalXp()
	{
		return config.goalType() == TreeRunningConfig.GoalType.XP
			? Math.max(1, Math.min(200_000_000, config.goalXp()))
			: XpTable.xpForLevel(Math.max(2, Math.min(99, config.goalLevel())));
	}

	/** The run's patches in route order, with what you last saw of each. */
	private List<RunTask> currentTasks(PlanSettings settings)
	{
		long now = System.currentTimeMillis();
		List<RunTask> tasks = RunPlanner.buildTasks(settings, client.getRealSkillLevel(Skill.FARMING), state.plantedAt, now);
		return routeOrder.sort(RunPlanner.applySeen(tasks, state.seen, state.plantedAt, now));
	}

	private long price(int itemId)
	{
		return itemManager.getItemPriceWithSource(itemId, true);
	}

	/** Recomputes everything shown in the panel and overlays. Must run on the client thread. */
	private void refresh()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			publish(PanelData.EMPTY);
			return;
		}

		finishIfStale();

		PlanSettings settings = buildSettings();
		int xp = client.getSkillExperience(Skill.FARMING);
		int level = client.getRealSkillLevel(Skill.FARMING);
		int goalXp = settings.getGoalXp();
		long now = System.currentTimeMillis();

		List<Integer> runXp = new ArrayList<>();
		for (RunRecord r : state.runs)
		{
			runXp.add(r.xp);
		}
		XpProjection planned = XpProjection.toGoal(xp, settings);
		int counted = Math.min(config.averageOver(), runXp.size());
		double actual = XpProjection.averageOfRecent(runXp, config.averageOver());

		boolean fromActual = actual > 0;
		int runsLeft = fromActual ? XpProjection.runsAtRate(xp, goalXp, actual) : planned.getRuns();
		if (runsLeft < 0 || (!fromActual && !planned.reachesGoal()))
		{
			runsLeft = -1;
		}

		Map<CropType, Integer> plantings = runsLeft > 0
			? XpProjection.forRuns(xp, runsLeft, settings).getPlantings()
			: Collections.emptyMap();
		Map<Integer, Integer> bank = state.bank;
		Map<Integer, Integer> vault = state.vault;
		Map<Integer, Integer> inv = inventory;
		List<SupplyCalculator.SupplyLine> supplies = SupplyCalculator.compute(plantings,
			id -> bank.getOrDefault(id, 0) + vault.getOrDefault(id, 0) + inv.getOrDefault(id, 0),
			id -> itemManager.getItemPriceWithSource(id, true));

		List<RunTask> tasks = currentTasks(settings);
		Set<Integer> produce = new HashSet<>();
		for (RunTask task : tasks)
		{
			if (task.getCrop().getProduce() != null)
			{
				produce.add(task.getCrop().getProduce().getId());
			}
		}
		runProduce = produce;
		HerbSettings herbSettings = buildHerbSettings(level);
		List<HerbTask> herbTasks = HerbPlanner.buildTasks(herbSettings, state.seen, now);

		PanelData d = new PanelData();
		d.loggedIn = true;
		d.currentXp = xp;
		d.level = level;
		d.goalType = config.goalType();
		d.goalLevel = config.goalLevel();
		d.goalXp = goalXp;
		d.plannedXpPerRun = planned.getAverageXpPerRun();
		d.plannedRuns = planned.reachesGoal() ? planned.getRuns() : -1;
		d.actualXpPerRun = actual;
		d.actualRunsCounted = counted;
		d.runsLeft = runsLeft;
		d.runsLeftFromActual = fromActual;
		d.runsPerDay = settings.getRunsPerDay();
		d.tasks = tasks;
		d.items = Route.build(tasks, bankStops, routeOrder);
		d.done = new HashSet<>(state.done);
		d.runActive = state.active;
		d.runStartedAt = state.startedAt;
		d.runXpSoFar = state.active ? Math.max(0, xp - state.startXp) : 0;
		d.lastMatch = lastMatch;
		d.needs = RunNeeds.compute(tasks, d.done, id -> inv.getOrDefault(id, 0));
		d.slots = InventoryFit.slotsFor(d.items, d.done);
		d.overflow = InventoryFit.check(d.items, d.done);
		d.supplies = supplies;
		d.bankSeenAt = state.bankSeenAt;
		d.vaultSeenAt = state.vaultSeenAt;
		d.runs = new ArrayList<>(state.runs);
		d.seen = new HashMap<>(state.seen);
		d.paid = new HashSet<>(state.paid);
		Set<String> unpaid = new HashSet<>();
		for (RunTask task : tasks)
		{
			if (state.done.contains(task.getKey()) && task.getCrop().getPayment() != null
				&& task.getLocation().getGardener() >= 0 && !state.paid.contains(task.getKey()))
			{
				unpaid.add(task.getKey());
			}
		}
		d.unpaid = unpaid;
		d.plantedAt = new HashMap<>(state.plantedAt);
		Map<RouteStep, String> travel = new EnumMap<>(RouteStep.class);
		for (RouteStep step : RouteStep.values())
		{
			travel.put(step, travelNote(step));
		}
		d.travel = travel;
		Map<HerbLocation, String> herbTravel = new EnumMap<>(HerbLocation.class);
		for (HerbLocation location : HerbLocation.values())
		{
			herbTravel.put(location, travelNote(location));
		}
		d.herbTravel = herbTravel;
		d.bankFilter = config.bankFilter();
		d.highlightGardeners = config.highlightGardeners();

		// Herbs
		Set<String> herbDone = new HashSet<>(state.herbDone);
		Map<Integer, Integer> carried = new HashMap<>(inv);
		equipment.forEach((k, v) -> carried.merge(k, v, Integer::sum));
		d.herbTasks = herbTasks;
		if (config.payForAllotments())
		{
			Set<String> unpaidAllotments = new HashSet<>();
			for (HerbTask task : herbTasks)
			{
				if (!task.isAllotment() || task.getLocation().getAllotmentGardener() < 0)
				{
					continue;
				}
				for (String patch : task.getPatchKeys())
				{
					if (herbDone.contains(HerbTask.stepKey(patch, HerbTask.PLANT)) && !state.paid.contains(patch))
					{
						unpaidAllotments.add(patch);
					}
				}
			}
			d.unpaidAllotments = unpaidAllotments;
		}
		d.herbDone = herbDone;
		d.herbActive = state.herbActive;
		d.herbStartedAt = state.herbStartedAt;
		d.herbNeeds = HerbPlanner.needs(herbTasks, herbDone, herbSettings, id -> carried.getOrDefault(id, 0));
		d.compost = herbSettings.compost;
		d.compostCarried = herbSettings.compost.isBottomless()
			? carried.getOrDefault(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 0) > 0 : true;
		d.secateursExpected = config.magicSecateurs();
		d.secateursCarried = carried.getOrDefault(ItemID.FAIRY_ENCHANTED_SECATEURS, 0) > 0;
		d.herbPicked = state.herbPicked;
		d.herbValue = state.herbValue;
		d.herbCost = state.herbCost;
		d.herbSeedCost = state.herbSeedCost;
		d.herbCompostCost = state.herbCompostCost;
		d.herbSeeds = new java.util.LinkedHashMap<>(state.herbSeeds);
		d.countSeeds = !config.ironmanSeeds();
		d.herbXp = state.herbXp;
		d.herbRuns = new ArrayList<>(state.herbRuns);
		d.herbLastMatch = herbLastMatch;
		d.picker = HerbPlanner.picker(herbSettings, id -> itemManager.getItemPriceWithSource(id, true));
		Map<String, Long> perPatch = new HashMap<>();
		for (HerbTask task : herbTasks)
		{
			if (!task.isAllotment())
			{
				perPatch.put(task.getKey(), HerbPlanner.estimate(task.getHerb(), task.getLocation(), herbSettings,
					id -> itemManager.getItemPriceWithSource(id, true)).getProfit());
			}
		}
		d.herbEstimates = perPatch;
		d.herbXpPerRun = HerbPlanner.xpPerRun(herbSettings);
		d.herbRunsPerDay = config.herbRunsPerDay();
		if (config.herbsOnTheWay())
		{
			Map<RouteStep, List<HerbTask>> onTheWay = new EnumMap<>(RouteStep.class);
			for (HerbTask task : herbTasks)
			{
				RouteStep step = task.getLocation().getTreeStep();
				if (step != null && !task.isAllotment() && task.isDue()
					&& task.getCondition() != PatchCondition.UNKNOWN)
				{
					onTheWay.computeIfAbsent(step, s -> new ArrayList<>()).add(task);
				}
			}
			d.onTheWay = onTheWay;
		}

		// Profit
		d.lifetimeTreeProfit = RunRecord.lifetimeProfit(state.runs);
		d.lifetimeHerbProfit = RunRecord.lifetimeProfit(state.herbRuns);
		d.lastTreeRun = RunRecord.lastWithProfit(state.runs);
		d.lastHerbRun = RunRecord.lastWithProfit(state.herbRuns);

		updateTagItems(d.items, d.done, herbTasks, herbDone);
		notifyHerbsGrown(herbTasks);
		publish(d);
	}

	/** One notification each time all your herb patches have finished growing. */
	private void notifyHerbsGrown(List<HerbTask> herbTasks)
	{
		if (!config.herbNotify())
		{
			return;
		}
		long allReady = 0;
		int herbPatches = 0;
		for (HerbTask task : herbTasks)
		{
			if (task.isAllotment())
			{
				continue;
			}
			herbPatches++;
			if (!task.isDue())
			{
				return;
			}
			SeenPatch s = state.seen.get(task.getKey());
			if (s == null)
			{
				return;
			}
			allReady = Math.max(allReady, s.readyBy());
		}
		if (herbPatches > 0 && allReady > 0 && allReady > state.herbNotifiedFor)
		{
			state.herbNotifiedFor = allReady;
			saveState();
			notifier.notify("Your herb patches should be grown.");
		}
	}

	private void publish(PanelData snapshot)
	{
		if (snapshot != PanelData.EMPTY)
		{
			snapshot.tagKey = treeTagItems.hashCode() * 31 + herbTagItems.hashCode();
		}
		PanelData previous = data;
		data = snapshot;
		if (panel != null)
		{
			SwingUtilities.invokeLater(() -> panel.update(snapshot));
		}
		// Keep an open filter up to date as patches are done.
		if (previous != null && isBankOpen())
		{
			String active = bankTagsService.getActiveTag();
			if ((TREE_TAG.equals(active) || HERB_TAG.equals(active)) && previous.tagKey != snapshot.tagKey)
			{
				openBankFilter();
			}
		}
	}

	// ------------------------------------------------------------------ helpers

	private int currentRegion()
	{
		WorldPoint point = playerLocation();
		return point == null ? -1 : point.getRegionID();
	}

	private WorldPoint playerLocation()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}
		return client.getTopLevelWorldView().isInstance()
			? WorldPoint.fromLocalInstance(client, player.getLocalLocation())
			: player.getWorldLocation();
	}

	private String where()
	{
		WorldPoint p = playerLocation();
		return p == null ? "unknown" : "region " + p.getRegionID() + " (" + p.getX() + "," + p.getY() + "," + p.getPlane() + ")";
	}

	private Map<Integer, Integer> countTracked(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(item.getId());
			if (trackedItems.contains(id))
			{
				counts.merge(id, item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private Map<Integer, Integer> countAll(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0)
				{
					counts.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return counts;
	}

	private void loadState()
	{
		String json = configManager.getRSProfileConfiguration(TreeRunningConfig.GROUP, STATE_KEY);
		RunState loaded = null;
		if (json != null && !json.isEmpty())
		{
			try
			{
				loaded = gson.fromJson(json, RunState.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Couldn't read saved farming run state, starting fresh", e);
			}
		}
		state = loaded != null ? loaded : new RunState();
		state.fillDefaults();
	}

	private void saveState()
	{
		configManager.setRSProfileConfiguration(TreeRunningConfig.GROUP, STATE_KEY, gson.toJson(state));
	}
}

package com.treerunning.core;

import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Ties a Farming XP drop to the patch it came from: check-health, planting, harvesting and
 * so on. A patch counts when its varbit changed within one tick of the XP, while you were
 * standing where that patch's varbit is sent. If more than one patch changed (a growth
 * tick landing at the same moment), it's too ambiguous and nothing is returned.
 * Patches are identified by key (a tree task key, or a herb or allotment key).
 */
public final class ActionMatcher
{
	/** How many ticks either side of the XP drop a patch change still counts. */
	public static final int WINDOW_TICKS = 1;

	public static final class Change
	{
		final int tick;
		final String patch;

		public Change(int tick, String patch)
		{
			this.tick = tick;
			this.patch = patch;
		}

		public int tick()
		{
			return tick;
		}

		public String patch()
		{
			return patch;
		}
	}

	private ActionMatcher()
	{
	}

	/**
	 * @param xpTick  the tick the Farming XP arrived
	 * @param changes recent patch changes where you were standing
	 * @param skip    patches that shouldn't be ticked again (already done, or switched off)
	 * @return the one patch the XP came from, or null if none or several
	 */
	public static String find(int xpTick, Collection<Change> changes, Set<String> skip)
	{
		Set<String> candidates = new LinkedHashSet<>();
		for (Change change : changes)
		{
			if (Math.abs(change.tick - xpTick) <= WINDOW_TICKS && !skip.contains(change.patch))
			{
				candidates.add(change.patch);
			}
		}
		return candidates.size() == 1 ? candidates.iterator().next() : null;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;

/**
 * A bank stop the player added to their route, before or after one stop's patches.
 * Saved as JSON in the plugin settings, so fields stay simple.
 */
public final class BankStop
{
	/** Stable ID, so a stop keeps its tick if it's renamed. */
	public String id;
	/** The RouteStep this bank stop belongs to (its enum name). */
	public String step;
	/** True to bank before planting the patches at this stop, false for after. */
	public boolean before = true;
	/** Where the player banks, as they typed it. */
	public String name = "";

	public BankStop()
	{
	}

	public BankStop(String id, RouteStep step, boolean before, String name)
	{
		this.id = id;
		this.step = step.name();
		this.before = before;
		this.name = name;
	}

	/** The stop this bank belongs to, or null if the saved step no longer exists. */
	public RouteStep getRouteStep()
	{
		for (RouteStep s : RouteStep.values())
		{
			if (s.name().equals(step))
			{
				return s;
			}
		}
		return null;
	}

	/** The key used to tick it off on a run. */
	public String getKey()
	{
		return "bank:" + id;
	}

	public String getLabel()
	{
		return "Bank: " + (name == null || name.trim().isEmpty() ? "bank stop" : name.trim());
	}
}

package com.treerunning.core;

import com.treerunning.data.AllotmentType;
import com.treerunning.data.Compost;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.HerbType;
import com.treerunning.data.PatchCondition;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import java.util.function.ToLongFunction;

/**
 * Herb runs: which patches need a visit, what to do at each, what to bring and what each
 * herb is worth per patch. Pure logic; the plugin supplies what it saw and the prices.
 */
public final class HerbPlanner
{
	private HerbPlanner()
	{
	}

	/**
	 * @param seen what each patch looked like when last seen, by task key
	 * @return every enabled herb patch (and allotment, where turned on), in location order
	 */
	public static List<HerbTask> buildTasks(HerbSettings settings, Map<String, SeenPatch> seen, long now)
	{
		List<HerbTask> tasks = new ArrayList<>();
		for (HerbLocation location : HerbLocation.values())
		{
			if (!settings.enabled.contains(location))
			{
				continue;
			}
			tasks.add(task(location, java.util.Collections.singletonList(HerbTask.keyFor(location, -1)),
				settings.herbAt(location), null, settings, seen, now));
			if (settings.allotments.contains(location) && location.getAllotmentCount() > 0)
			{
				List<String> keys = new ArrayList<>();
				for (int i = 0; i < location.getAllotmentCount(); i++)
				{
					keys.add(HerbTask.keyFor(location, i));
				}
				tasks.add(task(location, keys, null, settings.allotmentCrop, settings, seen, now));
			}
		}
		return tasks;
	}

	/** What a patch most likely looks like now; weeds on an empty patch still count as empty. */
	private static PatchCondition predict(SeenPatch s, long now)
	{
		if (s == null)
		{
			return PatchCondition.UNKNOWN;
		}
		PatchCondition c = s.predict(now);
		if ((c == PatchCondition.GROWING || c == PatchCondition.GROWN) && s.isWeeds())
		{
			return PatchCondition.EMPTY;
		}
		return c;
	}

	/** The one condition shown for several patches together: the most urgent one. */
	private static int urgency(PatchCondition c)
	{
		switch (c)
		{
			case DISEASED:
				return 6;
			case DEAD:
				return 5;
			case GROWN:
			case CHECK_HEALTH:
				return 4;
			case EMPTY:
			case STUMP:
				return 3;
			case UNKNOWN:
				return 2;
			default:
				return 1;
		}
	}

	private static HerbTask task(HerbLocation location, List<String> keys, HerbType herb, AllotmentType crop, HerbSettings settings,
		Map<String, SeenPatch> seenMap, long now)
	{
		boolean allotments = crop != null;
		int n = keys.size();
		PatchCondition condition = PatchCondition.GROWING;
		boolean anyGrown = false;
		boolean anyDiseased = false;
		boolean anyDead = false;
		boolean anySeen = false;
		String growing = null;
		long readyAt = 0;
		for (String key : keys)
		{
			SeenPatch s = seenMap.get(key);
			PatchCondition c = predict(s, now);
			anySeen |= s != null;
			if (urgency(c) > urgency(condition))
			{
				condition = c;
			}
			anyGrown |= c == PatchCondition.GROWN || c == PatchCondition.UNKNOWN;
			anyDiseased |= c == PatchCondition.DISEASED;
			anyDead |= c == PatchCondition.DEAD;
			if (s != null && !s.isWeeds() && s.crop != null && growing == null)
			{
				growing = s.crop;
			}
			if (c == PatchCondition.GROWING && s != null)
			{
				readyAt = readyAt == 0 ? s.readyBy() : Math.min(readyAt, s.readyBy());
			}
		}
		if (condition != PatchCondition.GROWING)
		{
			readyAt = 0;
		}

		String both = n > 1 ? (n == 2 ? " both allotments" : " the allotments") : allotments ? " the allotment" : "";
		String plant = herb != null ? herb.getDisplayName() : crop.getDisplayName();
		List<HerbTask.Step> steps = new ArrayList<>();
		if (anyDiseased)
		{
			steps.add(new HerbTask.Step(HerbTask.CURE, allotments ? "Cure or clear" + both.replace(" both", " the diseased") : "Cure it (plant cure) or clear it"));
		}
		if (anyDead)
		{
			steps.add(new HerbTask.Step(HerbTask.CLEAR, allotments ? "Clear the dead allotment" : "Clear the dead patch"));
		}
		if (anyGrown)
		{
			steps.add(new HerbTask.Step(HerbTask.HARVEST, allotments ? "Harvest" + both
				: "Harvest" + (growing != null ? " " + growing : "")));
		}
		if (settings.compost != Compost.NONE)
		{
			steps.add(new HerbTask.Step(HerbTask.COMPOST, allotments && n > 1 ? "Compost both" : "Compost"));
		}
		steps.add(new HerbTask.Step(HerbTask.PLANT, allotments
			? "Plant " + (AllotmentType.SEEDS_PER_PATCH * n) + " " + plant + " seeds"
			: "Plant " + plant));
		if (allotments && settings.payForAllotments && location.getAllotmentGardener() >= 0)
		{
			steps.add(new HerbTask.Step(HerbTask.PAY, "Pay " + crop.getPaymentQuantity() * n + " " + crop.getPaymentName()
				+ (n > 1 ? " (" + crop.getPaymentQuantity() + " each)" : "")));
		}
		return new HerbTask(location, allotments, herb, crop, condition, readyAt, anySeen, keys, steps);
	}

	// ------------------------------------------------------------------ what to bring

	/** One line of "This run needs". */
	public static final class Need
	{
		private final String name;
		private final int itemId;
		private final int needed;
		private final int carried;

		Need(String name, int itemId, int needed, int carried)
		{
			this.name = name;
			this.itemId = itemId;
			this.needed = needed;
			this.carried = carried;
		}

		public String getName()
		{
			return name;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getNeeded()
		{
			return needed;
		}

		public int getCarried()
		{
			return carried;
		}

		public boolean isShort()
		{
			return carried < needed;
		}
	}

	/**
	 * Seeds, compost and payments for the due patches not planted yet.
	 *
	 * @param done      step keys done this run
	 * @param inventory carried count by item ID (noted folded in)
	 */
	public static List<Need> needs(List<HerbTask> tasks, Set<String> done, HerbSettings settings, IntUnaryOperator inventory)
	{
		Map<Integer, Integer> seeds = new LinkedHashMap<>();
		Map<Integer, String> names = new LinkedHashMap<>();
		Map<Integer, Integer> payments = new LinkedHashMap<>();
		int compost = 0;
		for (HerbTask task : tasks)
		{
			if (!task.isDue())
			{
				continue;
			}
			int toPlant = task.getPatchCount() - task.doneCount(done, HerbTask.PLANT);
			if (toPlant <= 0)
			{
				continue;
			}
			if (task.getHerb() != null)
			{
				seeds.merge(task.getHerb().getSeedId(), 1, Integer::sum);
				names.put(task.getHerb().getSeedId(), task.getHerb().getDisplayName() + " seed");
			}
			else
			{
				AllotmentType crop = task.getAllotmentCrop();
				seeds.merge(crop.getSeedId(), AllotmentType.SEEDS_PER_PATCH * toPlant, Integer::sum);
				names.put(crop.getSeedId(), crop.getDisplayName() + " seed");
				int toPay = task.getPatchCount() - task.doneCount(done, HerbTask.PAY);
				if (settings.payForAllotments && task.getLocation().getAllotmentGardener() >= 0 && toPay > 0)
				{
					payments.merge(crop.getPaymentId(), crop.getPaymentQuantity() * toPay, Integer::sum);
					names.put(crop.getPaymentId(), crop.getPaymentName());
				}
			}
			if (settings.compost != Compost.NONE)
			{
				compost += task.getPatchCount() - task.doneCount(done, HerbTask.COMPOST);
			}
		}
		List<Need> lines = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : seeds.entrySet())
		{
			lines.add(new Need(names.get(e.getKey()), e.getKey(), e.getValue(), inventory.applyAsInt(e.getKey())));
		}
		for (Map.Entry<Integer, Integer> e : payments.entrySet())
		{
			lines.add(new Need(names.get(e.getKey()), e.getKey(), e.getValue(), inventory.applyAsInt(e.getKey())));
		}
		if (compost > 0 && !settings.compost.isBottomless())
		{
			int id = settings.compost.getItemId();
			lines.add(new Need(settings.compost.toString(), id, compost, inventory.applyAsInt(id)));
		}
		return lines;
	}

	// ------------------------------------------------------------------ yield, XP and profit

	/**
	 * The chance to keep a harvest life on each pick, from the OSRS Wiki's herb calculator:
	 * floor(floor(low × (99 − L)/98 + 80 × (L − 1)/98) × (1 + items) × (1 + diary) + 1) / 256.
	 */
	public static double chanceToSave(HerbType herb, int level, double itemBonus, double patchBonus)
	{
		double base = Math.floor(herb.getChanceToSaveAt1() * (99.0 - level) / 98.0 + 80.0 * (level - 1.0) / 98.0);
		return Math.floor(base * (1.0 + itemBonus) * (1.0 + patchBonus) + 1.0) / 256.0;
	}

	/** Herbs picked from a grown patch on average: lives ÷ (1 − chance to save). */
	public static double expectedYield(HerbType herb, HerbLocation location, HerbSettings settings)
	{
		int lives = settings.compost.getHarvestLives();
		double save = chanceToSave(herb, settings.farmingLevel, settings.itemBonus, settings.patchBonus(location));
		return lives / (1.0 - save);
	}

	/**
	 * The chance the patch survives to harvest: 1 for a disease-free patch, otherwise the
	 * chance of avoiding disease on each of its three later growth cycles. Plant cure and
	 * Resurrect Crops are left out.
	 */
	public static double survival(HerbLocation location, HerbSettings settings)
	{
		if (location.isDiseaseFree())
		{
			return 1.0;
		}
		double perCycle = settings.compost.getDiseaseChance() / 128.0;
		return Math.pow(1.0 - perCycle, 3);
	}

	/** Estimated profit and XP for one herb in one patch. */
	public static final class Estimate
	{
		private final HerbType herb;
		private final double herbs;
		private final double xp;
		private final long value;
		private final long seedCost;
		private final long profit;

		Estimate(HerbType herb, double herbs, double xp, long value, long seedCost, long profit)
		{
			this.herb = herb;
			this.herbs = herbs;
			this.xp = xp;
			this.value = value;
			this.seedCost = seedCost;
			this.profit = profit;
		}

		/** The herbs picked on average, at the herb's price. */
		public long getValue()
		{
			return value;
		}

		/** The seed's price, or 0 when seed costs aren't counted (ironman). */
		public long getSeedCost()
		{
			return seedCost;
		}

		public HerbType getHerb()
		{
			return herb;
		}

		public double getHerbs()
		{
			return herbs;
		}

		public double getXp()
		{
			return xp;
		}

		public long getProfit()
		{
			return profit;
		}
	}

	/**
	 * @param price price of an item by ID (seeds, herbs, compost)
	 */
	public static Estimate estimate(HerbType herb, HerbLocation location, HerbSettings settings, ToLongFunction<Integer> price)
	{
		double alive = survival(location, settings);
		double herbs = expectedYield(herb, location, settings) * alive;
		// Planting XP is given with the last herb, so a patch that dies gives none.
		double xp = herb.getPlantXp() * alive + herb.getHarvestXp() * herbs;
		double compostCost = settings.compost.getItemId() > 0
			? price.applyAsLong(settings.compost.getItemId()) * settings.compost.getBucketsPerUse() : 0;
		long value = Math.round(herbs * price.applyAsLong(herb.getHerbId()));
		long seed = settings.countSeeds ? price.applyAsLong(herb.getSeedId()) : 0;
		long profit = Math.round(value - seed - compostCost);
		return new Estimate(herb, herbs, xp, value, seed, profit);
	}

	/** Every herb you can plant, best profit first, for an average (not disease-free) patch. */
	public static List<Estimate> picker(HerbSettings settings, ToLongFunction<Integer> price)
	{
		List<Estimate> rows = new ArrayList<>();
		for (HerbType herb : HerbType.values())
		{
			if (herb.getLevel() <= settings.farmingLevel)
			{
				rows.add(estimate(herb, HerbLocation.ARDOUGNE, settings, price));
			}
		}
		rows.sort((a, b) -> Long.compare(b.getProfit(), a.getProfit()));
		return rows;
	}

	/** Expected Farming XP from one herb run over every enabled herb patch. */
	public static double xpPerRun(HerbSettings settings)
	{
		double xp = 0;
		for (HerbLocation location : settings.enabled)
		{
			HerbType herb = settings.herbAt(location);
			if (herb.getLevel() <= settings.farmingLevel)
			{
				xp += estimate(herb, location, settings, id -> 0L).getXp();
			}
		}
		return xp;
	}
}

package com.treerunning.core;

import com.treerunning.data.AllotmentType;
import com.treerunning.data.Compost;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.HerbType;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** Everything the herb planner needs from the settings. */
public final class HerbSettings
{
	public final Map<HerbLocation, HerbType> herbs;
	public final Set<HerbLocation> enabled;
	public final Set<HerbLocation> allotments;
	public final AllotmentType allotmentCrop;
	public final boolean payForAllotments;
	public final Compost compost;
	public final int farmingLevel;
	/** Magic secateurs (+10%) and a farming cape (+5%), as fractions added together. */
	public final double itemBonus;
	/** 0, 0.05, 0.10 or 0.15 at Catherby from the Kandarin diary. */
	public final double kandarinBonus;
	public final boolean kourendHard;
	/** False for ironman accounts that don't buy seeds: seeds then cost nothing in profit. */
	public final boolean countSeeds;

	public HerbSettings(Map<HerbLocation, HerbType> herbs, Set<HerbLocation> enabled, Set<HerbLocation> allotments,
		AllotmentType allotmentCrop, boolean payForAllotments, Compost compost, int farmingLevel, double itemBonus,
		double kandarinBonus, boolean kourendHard, boolean countSeeds)
	{
		this.herbs = Collections.unmodifiableMap(new EnumMap<>(herbs.isEmpty() ? new EnumMap<>(HerbLocation.class) : herbs));
		this.enabled = Collections.unmodifiableSet(enabled.isEmpty() ? EnumSet.noneOf(HerbLocation.class) : EnumSet.copyOf(enabled));
		this.allotments = Collections.unmodifiableSet(allotments.isEmpty() ? EnumSet.noneOf(HerbLocation.class) : EnumSet.copyOf(allotments));
		this.allotmentCrop = allotmentCrop;
		this.payForAllotments = payForAllotments;
		this.compost = compost;
		this.farmingLevel = farmingLevel;
		this.itemBonus = itemBonus;
		this.kandarinBonus = kandarinBonus;
		this.kourendHard = kourendHard;
		this.countSeeds = countSeeds;
	}

	public HerbType herbAt(HerbLocation location)
	{
		HerbType h = herbs.get(location);
		return h != null ? h : HerbType.RANARR;
	}

	/** The location's extra yield, from diaries. */
	public double patchBonus(HerbLocation location)
	{
		switch (location.getBonus())
		{
			case KANDARIN:
				return kandarinBonus;
			case KOUREND_HARD:
				return kourendHard ? 0.05 : 0;
			default:
				return 0;
		}
	}
}

package com.treerunning.core;

import com.treerunning.data.AllotmentType;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.HerbType;
import com.treerunning.data.PatchCondition;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * One entry on a herb run: a location's herb patch, or all of its allotments together.
 * Steps are tracked per patch underneath ("allot:HOSIDIUS:0|plant"), and a step on the
 * allotment entry counts as done once every allotment there has done it.
 */
public final class HerbTask
{
	public static final String HARVEST = "harvest";
	public static final String CURE = "cure";
	public static final String CLEAR = "clear";
	public static final String COMPOST = "compost";
	public static final String PLANT = "plant";
	public static final String PAY = "pay";

	/** A step at a patch: harvest, compost, plant and so on. */
	public static final class Step
	{
		private final String id;
		private final String label;

		Step(String id, String label)
		{
			this.id = id;
			this.label = label;
		}

		public String getId()
		{
			return id;
		}

		public String getLabel()
		{
			return label;
		}
	}

	private final HerbLocation location;
	private final boolean allotments;
	private final HerbType herb;
	private final AllotmentType allotmentCrop;
	private final PatchCondition condition;
	private final long readyAt;
	private final boolean seen;
	private final List<String> patchKeys;
	private final List<Step> steps;

	HerbTask(HerbLocation location, boolean allotments, HerbType herb, AllotmentType allotmentCrop, PatchCondition condition,
		long readyAt, boolean seen, List<String> patchKeys, List<Step> steps)
	{
		this.location = location;
		this.allotments = allotments;
		this.herb = herb;
		this.allotmentCrop = allotmentCrop;
		this.condition = condition;
		this.readyAt = readyAt;
		this.seen = seen;
		this.patchKeys = Collections.unmodifiableList(new ArrayList<>(patchKeys));
		this.steps = Collections.unmodifiableList(steps);
	}

	/** The key of one patch: "herb:FALADOR", or "allot:FALADOR:0" for an allotment. */
	public static String keyFor(HerbLocation location, int allotment)
	{
		return allotment < 0 ? "herb:" + location.name() : "allot:" + location.name() + ":" + allotment;
	}

	/** The key of a location's allotments together, as one entry. */
	public static String allotmentsKey(HerbLocation location)
	{
		return "allot:" + location.name();
	}

	public static String stepKey(String patchKey, String step)
	{
		return patchKey + "|" + step;
	}

	public String getKey()
	{
		return allotments ? allotmentsKey(location) : keyFor(location, -1);
	}

	/** The patches this entry covers: one herb patch, or every allotment at the location. */
	public List<String> getPatchKeys()
	{
		return patchKeys;
	}

	/** The per-patch step keys for a step. */
	public List<String> stepKeys(String step)
	{
		List<String> keys = new ArrayList<>(patchKeys.size());
		for (String k : patchKeys)
		{
			keys.add(stepKey(k, step));
		}
		return keys;
	}

	/** Done once every patch here has done it. */
	public boolean isDone(Set<String> done, String step)
	{
		for (String k : patchKeys)
		{
			if (!done.contains(stepKey(k, step)))
			{
				return false;
			}
		}
		return true;
	}

	/** How many of the patches here have done it. */
	public int doneCount(Set<String> done, String step)
	{
		int n = 0;
		for (String k : patchKeys)
		{
			if (done.contains(stepKey(k, step)))
			{
				n++;
			}
		}
		return n;
	}

	public HerbLocation getLocation()
	{
		return location;
	}

	public boolean isAllotment()
	{
		return allotments;
	}

	/** How many patches this entry covers (2 for most allotment pairs). */
	public int getPatchCount()
	{
		return patchKeys.size();
	}

	/** The herb to plant, or null for allotments. */
	public HerbType getHerb()
	{
		return herb;
	}

	/** The allotment crop to plant, or null for a herb patch. */
	public AllotmentType getAllotmentCrop()
	{
		return allotmentCrop;
	}

	public String getPlantName()
	{
		return herb != null ? herb.getDisplayName() : allotmentCrop.getDisplayName();
	}

	public String getLabel()
	{
		return allotments ? (patchKeys.size() > 1 ? "Allotments" : "Allotment") : "Herb patch";
	}

	/** What the patch (or the allotments, taken together) most likely looks like now. */
	public PatchCondition getCondition()
	{
		return condition;
	}

	/** When it's grown at the latest, if growing; 0 otherwise. */
	public long getReadyAt()
	{
		return readyAt;
	}

	/** False until the patch has been seen in game. */
	public boolean isSeen()
	{
		return seen;
	}

	/** Whether there's something to do here now. */
	public boolean isDue()
	{
		return condition != PatchCondition.GROWING;
	}

	public List<Step> getSteps()
	{
		return steps;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import com.treerunning.data.RouteStep;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Whether a tree run fits in one inventory between bank stops. Saplings don't stack, so
 * each takes a slot; payments are counted as one noted stack per item; a spade, coins and
 * each stop's teleport item take a slot each.
 */
public final class InventoryFit
{
	public static final int SLOTS = 28;
	/** Spade and coins. */
	static final int FIXED_SLOTS = 2;

	/** A stretch of the route that needs more than one inventory. */
	public static final class Overflow
	{
		private final int slots;
		private final RouteStep bankBefore;

		Overflow(int slots, RouteStep bankBefore)
		{
			this.slots = slots;
			this.bankBefore = bankBefore;
		}

		/** Slots the stretch needs. */
		public int getSlots()
		{
			return slots;
		}

		/** The stop to add a bank stop before, so the first part fits. */
		public RouteStep getBankBefore()
		{
			return bankBefore;
		}
	}

	private InventoryFit()
	{
	}

	/** Slots the whole remaining run needs from the next bank stop on (ignoring later bank stops). */
	public static int slotsFor(List<RouteItem> items, Set<String> done)
	{
		Counter c = new Counter();
		for (RouteItem item : items)
		{
			if (!item.isBank() && item.isDue() && !done.contains(item.getKey()))
			{
				c.add(item);
			}
		}
		return c.slots();
	}

	/**
	 * The first stretch between bank stops that won't fit in 28 slots, or null if every
	 * stretch fits. Only patches still to do count.
	 */
	public static Overflow check(List<RouteItem> items, Set<String> done)
	{
		Counter c = new Counter();
		RouteStep overflowAt = null;
		for (RouteItem item : items)
		{
			if (item.isBank())
			{
				if (done.contains(item.getKey()))
				{
					continue;
				}
				if (c.slots() > SLOTS)
				{
					return new Overflow(c.slots(), overflowAt);
				}
				c = new Counter();
				overflowAt = null;
				continue;
			}
			if (!item.isDue() || done.contains(item.getKey()))
			{
				continue;
			}
			c.add(item);
			if (overflowAt == null && c.slots() > SLOTS)
			{
				overflowAt = item.getStep();
			}
		}
		return c.slots() > SLOTS ? new Overflow(c.slots(), overflowAt) : null;
	}

	private static final class Counter
	{
		int saplings;
		final Set<Integer> payments = new HashSet<>();
		final Set<String> teleports = new HashSet<>();

		void add(RouteItem item)
		{
			CropType crop = item.getTask().getCrop();
			saplings++;
			if (crop.getPayment() != null)
			{
				payments.add(crop.getPayment().getId());
			}
			String carry = item.getStep().getCarryItem();
			if (carry != null)
			{
				teleports.add(carry);
			}
		}

		int slots()
		{
			return saplings == 0 ? 0 : saplings + payments.size() + teleports.size() + FIXED_SLOTS;
		}
	}
}

package com.treerunning.core;

import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import java.util.Collection;
import java.util.List;
import java.util.Set;

/**
 * Decides which checklist patch you just planted.
 *
 * In order of confidence:
 * 1. A patch of the right type whose varbit changed around the moment you planted, in the
 *    region you're standing in. This tells the three Fossil Island patches apart.
 * 2. A patch of the right type in the region you're standing in.
 * 3. The next unplanted patch of that type in route order (for anywhere the plugin has no
 *    region data, or if something unexpected happens).
 */
public final class PatchMatcher
{
	public enum Confidence
	{
		/** Matched by the patch's own state change. */
		PATCH,
		/** Matched by where you're standing. */
		REGION,
		/** Guessed from route order. */
		ROUTE
	}

	public static final class Match
	{
		private final RunTask task;
		private final Confidence confidence;

		Match(RunTask task, Confidence confidence)
		{
			this.task = task;
			this.confidence = confidence;
		}

		public RunTask getTask()
		{
			return task;
		}

		public Confidence getConfidence()
		{
			return confidence;
		}
	}

	private PatchMatcher()
	{
	}

	/**
	 * @param tasks          the run's checklist, in route order
	 * @param done           task keys already planted this run
	 * @param type           the patch type of what was planted
	 * @param region         the region ID you're standing in (-1 if unknown)
	 * @param changedPatches patches whose varbit changed just before/after planting
	 * @return the matched task, or null if every patch of that type is already ticked
	 */
	public static Match match(List<RunTask> tasks, Set<String> done, PatchType type, int region,
		Collection<PatchLocation> changedPatches)
	{
		for (RunTask task : tasks)
		{
			if (open(task, done, type) && changedPatches.contains(task.getLocation()) && task.getLocation().isInRegion(region))
			{
				return new Match(task, Confidence.PATCH);
			}
		}

		for (RunTask task : tasks)
		{
			if (open(task, done, type) && task.getLocation().isInRegion(region))
			{
				return new Match(task, Confidence.REGION);
			}
		}

		// You're at a stop that has this kind of patch, but it's already ticked (usually by
		// its check-health a moment ago). Don't guess another stop.
		for (RunTask task : tasks)
		{
			if (task.getLocation().getPatchType() == type && task.getLocation().isInRegion(region))
			{
				return null;
			}
		}

		// Planted somewhere the plugin can't place. Fall back to route order, but only
		// among due patches.
		for (RunTask task : tasks)
		{
			if (open(task, done, type) && task.isDue())
			{
				return new Match(task, Confidence.ROUTE);
			}
		}
		return null;
	}

	/** Not ticked yet and the right type. Not-due patches count too: you can only plant where it's ready. */
	private static boolean open(RunTask task, Set<String> done, PatchType type)
	{
		return !done.contains(task.getKey()) && task.getLocation().getPatchType() == type;
	}
}

