	{
		return enabled.contains(location) && crops.get(location.getPatchType()) != null;
	}

	public int getGoalXp()
	{
		return goalXp;
	}

	public int getRunsPerDay()
	{
		return runsPerDay;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * Puts patches and bank stops in the order you do them: stops in the player's order, and at
 * each stop the bank stops set to "before", then its patches, then the bank stops set to "after".
 */
public final class Route
{
	private Route()
	{
	}

	public static List<RouteItem> build(List<RunTask> tasks, List<BankStop> bankStops)
	{
		return build(tasks, bankStops, RouteOrder.defaults());
	}

	/** Tasks should already be sorted with {@link RouteOrder#sort}. */
	public static List<RouteItem> build(List<RunTask> tasks, List<BankStop> bankStops, RouteOrder order)
	{
		List<RouteItem> items = new ArrayList<>();
		for (RouteStep step : order.getStops())
		{
			addBanks(items, step, bankStops, true);
			for (RunTask task : tasks)
			{
				if (task.getStep() == step)
				{
					items.add(RouteItem.patch(task));
				}
			}
			addBanks(items, step, bankStops, false);
		}
		return items;
	}

	private static void addBanks(List<RouteItem> items, RouteStep step, List<BankStop> bankStops, boolean before)
	{
		for (BankStop bank : bankStops)
		{
			if (bank.getRouteStep() == step && bank.before == before)
			{
				items.add(RouteItem.bank(step, bank));
			}
		}
	}

	/**
	 * The next thing to do: the first unplanted due patch, or a bank stop that still has
	 * unplanted due patches after it. Null when the run is finished.
	 */
	public static RouteItem next(List<RouteItem> items, Set<String> done)
	{
		for (int i = 0; i < items.size(); i++)
		{
			RouteItem item = items.get(i);
			if (done.contains(item.getKey()))
			{
				continue;
			}
			if (!item.isBank())
			{
				if (item.getTask().isDue())
				{
					return item;
				}
			}
			else if (hasPatchAfter(items, i, done))
			{
				return item;
			}
		}
		return null;
	}

	private static boolean hasPatchAfter(List<RouteItem> items, int index, Set<String> done)
	{
		for (int j = index + 1; j < items.size(); j++)
		{
			RouteItem later = items.get(j);
			if (!later.isBank() && later.getTask().isDue() && !done.contains(later.getKey()))
			{
				return true;
			}
		}
		return false;
	}

	/** The first stop after this one that still has something to do. */
	public static RouteStep stepAfter(List<RouteItem> items, RouteItem current, Set<String> done)
	{
		boolean passed = false;
		for (RouteItem item : items)
		{
			if (item == current)
			{
				passed = true;
				continue;
			}
			if (passed && item.getStep() != current.getStep() && item.isDue() && !done.contains(item.getKey()))
			{
				return item.getStep();
			}
		}
		return null;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;

/**
 * One line of the run, in order: a patch to plant or a bank stop.
 */
public final class RouteItem
{
	private final RouteStep step;
	private final RunTask task;
	private final BankStop bank;

	private RouteItem(RouteStep step, RunTask task, BankStop bank)
	{
		this.step = step;
		this.task = task;
		this.bank = bank;
	}

	static RouteItem patch(RunTask task)
	{
		return new RouteItem(task.getStep(), task, null);
	}

	static RouteItem bank(RouteStep step, BankStop bank)
	{
		return new RouteItem(step, null, bank);
	}

	public RouteStep getStep()
	{
		return step;
	}

	public boolean isBank()
	{
		return bank != null;
	}

	/** The patch, or null for a bank stop. */
	public RunTask getTask()
	{
		return task;
	}

	/** The bank stop, or null for a patch. */
	public BankStop getBank()
	{
		return bank;
	}

	public String getKey()
	{
		return isBank() ? bank.getKey() : task.getKey();
	}

	/** Patches that aren't ready yet can't be done; bank stops always can. */
	public boolean isDue()
	{
		return isBank() || task.isDue();
	}
}

package com.treerunning.core;

import com.treerunning.data.PatchLocation;
import com.treerunning.data.RouteStep;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The order you visit the stops in, and the order of the patches at each stop. Anything the
 * player hasn't moved keeps its built-in order. Saved as two JSON settings.
 */
public final class RouteOrder
{
	private final List<RouteStep> stops;
	private final Map<RouteStep, List<PatchLocation>> patches;

	private RouteOrder(List<RouteStep> stops, Map<RouteStep, List<PatchLocation>> patches)
	{
		this.stops = stops;
		this.patches = patches;
	}

	/** The built-in order. */
	public static RouteOrder defaults()
	{
		return of(Collections.emptyList(), Collections.emptyMap());
	}

	/**
	 * Builds an order from saved names. Unknown names are ignored and anything missing is
	 * added in its built-in position, so new stops and patches always appear.
	 */
	public static RouteOrder fromNames(List<String> stopNames, Map<String, List<String>> patchNames)
	{
		List<RouteStep> stops = new ArrayList<>();
		if (stopNames != null)
		{
			for (String name : stopNames)
			{
				RouteStep step = step(name);
				if (step != null && !stops.contains(step))
				{
					stops.add(step);
				}
			}
		}
		Map<RouteStep, List<PatchLocation>> patches = new EnumMap<>(RouteStep.class);
		if (patchNames != null)
		{
			for (Map.Entry<String, List<String>> e : patchNames.entrySet())
			{
				RouteStep step = step(e.getKey());
				if (step == null || e.getValue() == null)
				{
					continue;
				}
				List<PatchLocation> list = new ArrayList<>();
				for (String name : e.getValue())
				{
					PatchLocation location = location(name);
					if (location != null && location.getStep() == step && !list.contains(location))
					{
						list.add(location);
					}
				}
				patches.put(step, list);
			}
		}
		return of(stops, patches);
	}

	private static RouteOrder of(List<RouteStep> savedStops, Map<RouteStep, List<PatchLocation>> savedPatches)
	{
		List<RouteStep> stops = new ArrayList<>(savedStops);
		for (RouteStep step : RouteStep.values())
		{
			if (!stops.contains(step))
			{
				// Put new stops after the stop that comes before them in the built-in order.
				int at = stops.size();
				for (int i = step.ordinal() - 1; i >= 0; i--)
				{
					int idx = stops.indexOf(RouteStep.values()[i]);
					if (idx >= 0)
					{
						at = idx + 1;
						break;
					}
				}
				if (step.ordinal() == 0)
				{
					at = 0;
				}
				stops.add(at, step);
			}
		}
		Map<RouteStep, List<PatchLocation>> patches = new EnumMap<>(RouteStep.class);
		for (RouteStep step : RouteStep.values())
		{
			List<PatchLocation> list = new ArrayList<>(savedPatches.getOrDefault(step, Collections.emptyList()));
			for (PatchLocation location : PatchLocation.values())
			{
				if (location.getStep() == step && !list.contains(location))
				{
					list.add(location);
				}
			}
			patches.put(step, Collections.unmodifiableList(list));
		}
		return new RouteOrder(Collections.unmodifiableList(stops), Collections.unmodifiableMap(patches));
	}

	public List<RouteStep> getStops()
	{
		return stops;
	}

	public List<PatchLocation> getPatches(RouteStep step)
	{
		return patches.get(step);
	}

	public List<String> stopNames()
	{
		List<String> names = new ArrayList<>();
		for (RouteStep step : stops)
		{
			names.add(step.name());
		}
		return names;
	}

	public Map<String, List<String>> patchNames()
	{
		Map<String, List<String>> names = new HashMap<>();
		for (Map.Entry<RouteStep, List<PatchLocation>> e : patches.entrySet())
		{
			List<String> list = new ArrayList<>();
			for (PatchLocation location : e.getValue())
			{
				list.add(location.name());
			}
			names.put(e.getKey().name(), list);
		}
		return names;
	}

	/** Moves a stop earlier (-1) or later (+1) in the route. */
	public RouteOrder moveStop(RouteStep step, int direction)
	{
		List<RouteStep> list = new ArrayList<>(stops);
		int i = list.indexOf(step);
		int j = i + direction;
		if (i >= 0 && j >= 0 && j < list.size())
		{
			Collections.swap(list, i, j);
		}
		return of(list, patches);
	}

	/** Moves a patch up (-1) or down (+1) within its stop. */
	public RouteOrder movePatch(PatchLocation location, int direction)
	{
		Map<RouteStep, List<PatchLocation>> copy = new EnumMap<>(RouteStep.class);
		copy.putAll(patches);
		List<PatchLocation> list = new ArrayList<>(patches.get(location.getStep()));
		int i = list.indexOf(location);
		int j = i + direction;
		if (i >= 0 && j >= 0 && j < list.size())
		{
			Collections.swap(list, i, j);
		}
		copy.put(location.getStep(), list);
		return of(stops, copy);
	}

	/** Sorts tasks by stop, then by patch, in this order. */
	public List<RunTask> sort(List<RunTask> tasks)
	{
		List<RunTask> sorted = new ArrayList<>(tasks);
		sorted.sort(Comparator
			.comparingInt((RunTask t) -> stops.indexOf(t.getStep()))
			.thenComparingInt(t -> patches.get(t.getStep()).indexOf(t.getLocation()))
			.thenComparingInt(RunTask::getIndex));
		return Collections.unmodifiableList(sorted);
	}

	private static RouteStep step(String name)
	{
		for (RouteStep s : RouteStep.values())
		{
			if (s.name().equals(name))
			{
				return s;
			}
		}
		return null;
	}

	private static PatchLocation location(String name)
	{
		for (PatchLocation l : PatchLocation.values())
		{
			if (l.name().equals(name))
			{
				return l;
			}
		}
		return null;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/**
 * Saplings and protection payments the rest of this run needs, one line per crop in route
 * order, against what's in your inventory.
 */
public final class RunNeeds
{
	public static final class Line
	{
		private final CropType crop;
		private final int saplings;
		private final int saplingsCarried;
		private final int payment;
		private final int paymentCarried;

		Line(CropType crop, int saplings, int saplingsCarried, int payment, int paymentCarried)
		{
			this.crop = crop;
			this.saplings = saplings;
			this.saplingsCarried = saplingsCarried;
			this.payment = payment;
			this.paymentCarried = paymentCarried;
		}

		public CropType getCrop()
		{
			return crop;
		}

		/** Saplings (or Hespori seeds) still to plant. */
		public int getSaplings()
		{
			return saplings;
		}

		/** How many of those are in your inventory. */
		public int getSaplingsCarried()
		{
			return saplingsCarried;
		}

		/** Protection items still needed, 0 when the crop can't be protected (Hespori). */
		public int getPayment()
		{
			return payment;
		}

		/** How many of those are in your inventory (noted counts). */
		public int getPaymentCarried()
		{
			return paymentCarried;
		}

		public boolean isShort()
		{
			return saplingsCarried < saplings || paymentCarried < payment;
		}
	}

	private RunNeeds()
	{
	}

	/** Totals for the whole run, ignoring your inventory. */
	public static List<Line> compute(List<RunTask> tasks)
	{
		return compute(tasks, java.util.Collections.emptySet(), id -> Integer.MAX_VALUE / 4);
	}

	/**
	 * @param tasks     the run's patches, in route order
	 * @param done      patches already ticked (they don't need anything any more)
	 * @param inventory how many of an unnoted item ID you're carrying (noted copies included)
	 */
	public static List<Line> compute(List<RunTask> tasks, Set<String> done, IntUnaryOperator inventory)
	{
		Map<CropType, Integer> counts = new LinkedHashMap<>();
		for (RunTask task : tasks)
		{
			if (task.isDue() && !done.contains(task.getKey()))
			{
				counts.merge(task.getCrop(), 1, Integer::sum);
			}
		}

		// Several crops can share a payment item (coconuts for magic and dragonfruit), so
		// what you carry is handed out in route order.
		Map<Integer, Integer> pool = new HashMap<>();
		List<Line> lines = new ArrayList<>();
		for (Map.Entry<CropType, Integer> e : counts.entrySet())
		{
			CropType crop = e.getKey();
			int saplings = e.getValue();
			int saplingId = crop.getPlantedItem().getId();
			int saplingsCarried = take(pool, saplingId, saplings, inventory);

			int payment = 0;
			int paymentCarried = 0;
			if (crop.getPayment() != null)
			{
				payment = saplings * crop.getPaymentQuantity();
				paymentCarried = take(pool, crop.getPayment().getId(), payment, inventory);
			}
			lines.add(new Line(crop, saplings, saplingsCarried, payment, paymentCarried));
		}
		return lines;
	}

	private static int take(Map<Integer, Integer> pool, int id, int wanted, IntUnaryOperator inventory)
	{
		int left = pool.computeIfAbsent(id, inventory::applyAsInt);
		int got = Math.min(left, wanted);
		pool.put(id, left - got);
		return got;
	}

	public static int totalSaplings(List<Line> lines)
	{
		int total = 0;
		for (Line line : lines)
		{
			total += line.getSaplings();
		}
		return total;
	}

	public static int shortCount(List<Line> lines)
	{
		int n = 0;
		for (Line line : lines)
		{
			if (line.isShort())
			{
				n++;
			}
		}
		return n;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import com.treerunning.data.PatchCondition;
import com.treerunning.data.PatchLocation;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Builds the checklist for a run: every enabled patch in route order, with patches that
 * are still growing (or need a higher level) marked as not due.
 */
public final class RunPlanner
{
	private RunPlanner()
	{
	}

	/**
	 * @param plantedAt when each long-growing patch was last planted (task key → epoch millis)
	 */
	public static List<RunTask> buildTasks(PlanSettings settings, int farmingLevel, Map<String, Long> plantedAt, long nowMillis)
	{
		List<PatchLocation> locations = new ArrayList<>(Arrays.asList(PatchLocation.values()));
		locations.sort(Comparator
			.comparingInt((PatchLocation l) -> l.getStep().ordinal())
			.thenComparingInt(Enum::ordinal));

		List<RunTask> tasks = new ArrayList<>();
		for (PatchLocation location : locations)
		{
			if (!settings.isEnabled(location))
			{
				continue;
			}

			CropType crop = settings.cropFor(location.getPatchType());
			for (int i = 0; i < location.getPatchCount(); i++)
			{
				String key = RunTask.keyFor(location, i);
				boolean due = true;
				String note = null;

				if (crop.getLevel() > farmingLevel)
				{
					due = false;
					note = "Needs " + crop.getLevel() + " Farming";
				}
				else
				{
					// Every patch is timed from its last finished run, so a calquat (21 h) or fruit tree
					// (16 h) planted late yesterday isn't shown as due before it can have grown.
					Long planted = plantedAt.get(key);
					if (planted != null)
					{
						long readyAt = planted + crop.getGrowthMinutes() * 60_000L;
						if (nowMillis < readyAt)
						{
							due = false;
							note = "Ready in " + formatDuration(readyAt - nowMillis);
						}
					}
				}

				tasks.add(new RunTask(location, i, crop, due, note));
			}
		}
		return tasks;
	}

	/**
	 * Uses what each patch looked like when you last saw it, when that's newer than its timer:
	 * a patch still growing isn't due, and a grown, diseased, dead or empty one is.
	 *
	 * @param seen      last seen state by task key
	 * @param plantedAt when each patch was last planted on a finished run
	 */
	public static List<RunTask> applySeen(List<RunTask> tasks, Map<String, SeenPatch> seen, Map<String, Long> plantedAt, long now)
	{
		List<RunTask> out = new ArrayList<>(tasks.size());
		for (RunTask task : tasks)
		{
			SeenPatch s = seen.get(task.getKey());
			Long planted = plantedAt.get(task.getKey());
			boolean levelTooLow = task.getNote() != null && task.getNote().startsWith("Needs");
			if (s == null || levelTooLow || s.condition == PatchCondition.UNKNOWN || (planted != null && s.seenAt < planted))
			{
				out.add(task);
				continue;
			}
			PatchCondition now2 = s.predict(now);
			if (now2 == PatchCondition.GROWING && !s.isWeeds())
			{
				out.add(new RunTask(task.getLocation(), task.getIndex(), task.getCrop(), false,
					"Ready in " + formatDuration(s.readyBy() - now)));
			}
			else
			{
				out.add(new RunTask(task.getLocation(), task.getIndex(), task.getCrop(), true, task.getNote()));
			}
		}
		return out;
	}

	static String formatDuration(long millis)
	{
		long totalMinutes = Math.max(0, millis) / 60_000L;
		long hours = totalMinutes / 60;
		long minutes = totalMinutes % 60;
		if (hours >= 24)
		{
			return (hours / 24) + "d " + (hours % 24) + "h";
		}
		return hours + "h " + minutes + "m";
	}
}

package com.treerunning.core;

import java.util.List;

/**
 * One finished run in a run history (tree or herb). Saved as JSON, so fields stay simple.
 */
public final class RunRecord
{
	/** When the run was finished (epoch millis), or 0 for runs saved by older versions. */
	public long endedAt;
	/** Farming XP gained on the run. */
	public int xp;
	/** Patches ticked on the run, or -1 if unknown. */
	public int patches = -1;
	/** When the run started, or 0 if unknown (older versions). */
	public long startedAt;
	/** What the harvest was worth at the time (herbs, fruit, produce). */
	public long value;
	/** What the seeds, saplings, compost and payments used cost at the time. */
	public long cost;
	/** False for runs saved before profit was tracked. */
	public boolean profitTracked;
	/** Herbs or crops picked (herb runs). */
	public int picked;
	/** The part of cost that was seeds (0 when seed costs are off, for ironman accounts). */
	public long seedCost;
	/** The part of cost that was compost. */
	public long compostCost;

	public RunRecord()
	{
	}

	public RunRecord(long endedAt, int xp, int patches)
	{
		this.endedAt = endedAt;
		this.xp = xp;
		this.patches = patches;
	}

	public long profit()
	{
		return value - cost;
	}

	/** How long the run took, or 0 if unknown. */
	public long durationMs()
	{
		return startedAt > 0 && endedAt > startedAt ? endedAt - startedAt : 0;
	}

	/** The fastest run with this many patches, or 0 if none has a time. */
	public static long bestTime(List<RunRecord> runs, int patches)
	{
		long best = 0;
		for (RunRecord r : runs)
		{
			long d = r.durationMs();
			if (d > 0 && r.patches == patches && (best == 0 || d < best))
			{
				best = d;
			}
		}
		return best;
	}

	/** Profit over every run with profit tracked. */
	public static long lifetimeProfit(List<RunRecord> runs)
	{
		long total = 0;
		for (RunRecord r : runs)
		{
			if (r.profitTracked)
			{
				total += r.profit();
			}
		}
		return total;
	}

	/** The most recent run with profit tracked, or null. */
	public static RunRecord lastWithProfit(List<RunRecord> runs)
	{
		for (int i = runs.size() - 1; i >= 0; i--)
		{
			if (runs.get(i).profitTracked)
			{
				return runs.get(i);
			}
		}
		return null;
	}
}

