package com.treerunning.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.treerunning.data.AllotmentType;
import com.treerunning.data.Compost;
import com.treerunning.data.CropType;
import com.treerunning.data.HerbLocation;
import com.treerunning.data.HerbType;
import com.treerunning.data.PatchCondition;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class HerbPlannerTest
{
	private static final long NOW = 1_800_000_000_000L;

	private static HerbSettings settings(Set<HerbLocation> allotments, boolean pay)
	{
		Map<HerbLocation, HerbType> herbs = new EnumMap<>(HerbLocation.class);
		herbs.put(HerbLocation.TROLL_STRONGHOLD, HerbType.SNAPDRAGON);
		return new HerbSettings(herbs, EnumSet.of(HerbLocation.FALADOR, HerbLocation.CATHERBY, HerbLocation.TROLL_STRONGHOLD),
			allotments, AllotmentType.SNAPE_GRASS, pay, Compost.ULTRACOMPOST, 90, 0.10, 0.10, false, true);
	}

	@Test
	public void onlyEnabledPatchesAreListed()
	{
		List<HerbTask> tasks = HerbPlanner.buildTasks(settings(EnumSet.noneOf(HerbLocation.class), false), new HashMap<>(), NOW);
		assertEquals(3, tasks.size());
		for (HerbTask t : tasks)
		{
			assertFalse(t.getLocation() == HerbLocation.ARDOUGNE);
		}
		// Unseen patches count as due, with harvest, compost and plant.
		assertEquals(PatchCondition.UNKNOWN, tasks.get(0).getCondition());
		assertTrue(tasks.get(0).isDue());
		assertEquals(3, tasks.get(0).getSteps().size());
	}

	@Test
	public void allotmentsAreAddedWhereTurnedOn()
	{
		List<HerbTask> tasks = HerbPlanner.buildTasks(settings(EnumSet.of(HerbLocation.CATHERBY), true), new HashMap<>(), NOW);
		// Catherby's two allotments are one entry.
		assertEquals(4, tasks.size());
		HerbTask allot = null;
		for (HerbTask t : tasks)
		{
			if (t.isAllotment())
			{
				allot = t;
				break;
			}
		}
		assertEquals(AllotmentType.SNAPE_GRASS, allot.getAllotmentCrop());
		assertEquals(2, allot.getPatchCount());
		assertEquals("Plant 6 Snape grass seeds", allot.getSteps().get(allot.getSteps().size() - 2).getLabel());
		// Planting one allotment isn't the step done; both are.
		Set<String> one = new HashSet<>();
		one.add(HerbTask.stepKey(HerbTask.keyFor(HerbLocation.CATHERBY, 0), HerbTask.PLANT));
		assertFalse(allot.isDone(one, HerbTask.PLANT));
		assertEquals(1, allot.doneCount(one, HerbTask.PLANT));
		one.add(HerbTask.stepKey(HerbTask.keyFor(HerbLocation.CATHERBY, 1), HerbTask.PLANT));
		assertTrue(allot.isDone(one, HerbTask.PLANT));
		assertEquals(HerbTask.PAY, allot.getSteps().get(allot.getSteps().size() - 1).getId());

		List<HerbPlanner.Need> needs = HerbPlanner.needs(tasks, new HashSet<>(), settings(EnumSet.of(HerbLocation.CATHERBY), true), id -> 0);
		int snapeSeeds = 0;
		int jangerberries = 0;
		for (HerbPlanner.Need n : needs)
		{
			if (n.getItemId() == AllotmentType.SNAPE_GRASS.getSeedId())
			{
				snapeSeeds = n.getNeeded();
			}
			if (n.getItemId() == AllotmentType.SNAPE_GRASS.getPaymentId())
			{
				jangerberries = n.getNeeded();
			}
		}
		assertEquals(6, snapeSeeds);
		assertEquals(10, jangerberries);
	}

	@Test
	public void seenStatesDriveSteps()
	{
		Map<String, SeenPatch> seen = new HashMap<>();
		seen.put(HerbTask.keyFor(HerbLocation.FALADOR, -1), new SeenPatch(PatchCondition.DISEASED, 2, 5, 20, "Ranarr", NOW - 1000));
		seen.put(HerbTask.keyFor(HerbLocation.CATHERBY, -1), new SeenPatch(PatchCondition.GROWING, 1, 5, 20, "Ranarr", NOW - 10 * 60_000L));
		// Planted 90 minutes ago: grown by now.
		seen.put(HerbTask.keyFor(HerbLocation.TROLL_STRONGHOLD, -1), new SeenPatch(PatchCondition.GROWING, 0, 5, 20, "Snapdragon", NOW - 90 * 60_000L));
		List<HerbTask> tasks = HerbPlanner.buildTasks(settings(EnumSet.noneOf(HerbLocation.class), false), seen, NOW);
		HerbTask catherby = tasks.get(0);
		HerbTask falador = tasks.get(1);
		HerbTask troll = tasks.get(2);
		assertEquals(HerbLocation.CATHERBY, catherby.getLocation());
		assertFalse(catherby.isDue());
		assertEquals(NOW - 10 * 60_000L + 60 * 60_000L, catherby.getReadyAt());
		assertEquals(HerbTask.CURE, falador.getSteps().get(0).getId());
		assertEquals(PatchCondition.GROWN, troll.getCondition());

		// Catherby is still growing, so its seed isn't needed.
		Set<String> done = new HashSet<>(falador.stepKeys(HerbTask.PLANT));
		List<HerbPlanner.Need> needs = HerbPlanner.needs(tasks, done, settings(EnumSet.noneOf(HerbLocation.class), false), id -> 0);
		assertEquals(2, needs.size());
		assertEquals(HerbType.SNAPDRAGON.getSeedId(), needs.get(0).getItemId());
	}

	@Test
	public void chanceToSaveFollowsTheWikiFormula()
	{
		// Ranarr at 99 with no bonuses: floor(floor(80) * 1 + 1) / 256 = 81/256.
		assertEquals(81 / 256.0, HerbPlanner.chanceToSave(HerbType.RANARR, 99, 0, 0), 1e-9);
		// At level 1 it's the herb's low value: floor(39 + 1) / 256.
		assertEquals(40 / 256.0, HerbPlanner.chanceToSave(HerbType.RANARR, 1, 0, 0), 1e-9);
		// Secateurs and a diary multiply in before the +1.
		assertEquals(Math.floor(80 * 1.1 * 1.1 + 1) / 256.0, HerbPlanner.chanceToSave(HerbType.TORSTOL, 99, 0.10, 0.10), 1e-9);
		// Ultracompost's 6 lives at 99 with secateurs: about 8.6 herbs.
		HerbSettings s = settings(EnumSet.noneOf(HerbLocation.class), false);
		double y = HerbPlanner.expectedYield(HerbType.RANARR, HerbLocation.ARDOUGNE, s);
		assertTrue(y > 8.0 && y < 9.5);
		assertEquals(1.0, HerbPlanner.survival(HerbLocation.TROLL_STRONGHOLD, s), 1e-9);
		assertTrue(HerbPlanner.survival(HerbLocation.ARDOUGNE, s) < 1.0);
	}

	@Test
	public void estimateIsHerbsTimesPriceLessSeedAndCompost()
	{
		HerbSettings s = settings(EnumSet.noneOf(HerbLocation.class), false);
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(HerbType.RANARR.getHerbId(), 7000L);
		prices.put(HerbType.RANARR.getSeedId(), 40000L);
		prices.put(Compost.ULTRACOMPOST.getItemId(), 1000L);
		HerbPlanner.Estimate e = HerbPlanner.estimate(HerbType.RANARR, HerbLocation.TROLL_STRONGHOLD, s, id -> prices.getOrDefault(id, 0L));
		double herbs = HerbPlanner.expectedYield(HerbType.RANARR, HerbLocation.TROLL_STRONGHOLD, s);
		assertEquals(Math.round(herbs * 7000 - 40000 - 1000), e.getProfit());
		assertEquals(40000, e.getSeedCost());

		// Ironman: seeds cost nothing.
		Map<HerbLocation, HerbType> herbs2 = new EnumMap<>(HerbLocation.class);
		HerbSettings iron = new HerbSettings(herbs2, EnumSet.of(HerbLocation.TROLL_STRONGHOLD), EnumSet.noneOf(HerbLocation.class),
			AllotmentType.SNAPE_GRASS, false, Compost.ULTRACOMPOST, 90, 0.10, 0.10, false, false);
		HerbPlanner.Estimate i = HerbPlanner.estimate(HerbType.RANARR, HerbLocation.TROLL_STRONGHOLD, iron, id -> prices.getOrDefault(id, 0L));
		assertEquals(0, i.getSeedCost());
		assertEquals(Math.round(herbs * 7000 - 1000), i.getProfit());
	}

	// ---------------------------------------------------------------- tree helpers

	private static List<RunTask> treeTasks()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, CropType.YEW);
		crops.put(PatchType.FRUIT_TREE, CropType.PAPAYA);
		crops.put(PatchType.HARDWOOD, CropType.IRONWOOD);
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		PlanSettings s = new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), XpTable.xpForLevel(99), 1);
		return RunPlanner.buildTasks(s, 99, Collections.emptyMap(), NOW);
	}

	@Test
	public void seenGrowingTreeIsNotDue()
	{
		List<RunTask> tasks = treeTasks();
		Map<String, SeenPatch> seen = new HashMap<>();
		String varrock = RunTask.keyFor(PatchLocation.TREE_VARROCK, 0);
		String falador = RunTask.keyFor(PatchLocation.TREE_FALADOR, 0);
		seen.put(varrock, new SeenPatch(PatchCondition.GROWING, 3, 11, 40, "Yew", NOW - 60_000L));
		seen.put(falador, new SeenPatch(PatchCondition.DISEASED, 3, 11, 40, "Yew", NOW - 60_000L));
		List<RunTask> out = RunPlanner.applySeen(tasks, seen, new HashMap<>(), NOW);
		for (RunTask t : out)
		{
			if (t.getKey().equals(varrock))
			{
				assertFalse(t.isDue());
				assertTrue(t.getNote().startsWith("Ready in"));
			}
			if (t.getKey().equals(falador))
			{
				assertTrue(t.isDue());
			}
		}
		// A sighting older than the last planting is ignored.
		Map<String, Long> planted = new HashMap<>();
		planted.put(varrock, NOW);
		for (RunTask t : RunPlanner.applySeen(tasks, seen, planted, NOW))
		{
			if (t.getKey().equals(varrock))
			{
				assertTrue(t.isDue());
			}
		}
	}

	@Test
	public void inventoryWarningSuggestsABankStop()
	{
		List<RunTask> tasks = treeTasks();
		List<RouteItem> items = Route.build(tasks, new ArrayList<>(), RouteOrder.defaults());
		InventoryFit.Overflow o = InventoryFit.check(items, new HashSet<>());
		// Every patch at 99 with all teleports doesn't fit in one inventory.
		assertTrue(o != null && o.getSlots() > 28 && o.getBankBefore() != null);
		// Everything done: nothing to warn about.
		Set<String> done = new HashSet<>();
		for (RunTask t : tasks)
		{
			done.add(t.getKey());
		}
		assertNull(InventoryFit.check(items, done));
	}

	@Test
	public void bestTimeIsPerPatchCount()
	{
		List<RunRecord> runs = new ArrayList<>();
		RunRecord a = new RunRecord(10_000_000, 100, 19);
		a.startedAt = 10_000_000 - 900_000;
		RunRecord b = new RunRecord(20_000_000, 100, 19);
		b.startedAt = 20_000_000 - 800_000;
		RunRecord c = new RunRecord(30_000_000, 100, 24);
		c.startedAt = 30_000_000 - 600_000;
		runs.add(a);
		runs.add(b);
		runs.add(c);
		assertEquals(800_000, RunRecord.bestTime(runs, 19));
		assertEquals(600_000, RunRecord.bestTime(runs, 24));
		a.profitTracked = true;
		a.value = 500;
		a.cost = 200;
		assertEquals(300, RunRecord.lifetimeProfit(runs));
		assertEquals(a, RunRecord.lastWithProfit(runs));
	}
}

package com.treerunning.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import com.treerunning.data.RouteStep;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class OrderAndNeedsTest
{
	private static List<RunTask> tasks()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, CropType.YEW);
		crops.put(PatchType.FRUIT_TREE, CropType.PAPAYA);
		crops.put(PatchType.HARDWOOD, CropType.IRONWOOD);
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		PlanSettings s = new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), XpTable.xpForLevel(99), 1);
		return RunPlanner.buildTasks(s, 99, Collections.emptyMap(), 0);
	}

	// ---------------------------------------------------------------- RouteOrder

	@Test
	public void defaultsCoverEveryStopAndPatch()
	{
		RouteOrder order = RouteOrder.defaults();
		int patches = 0;
		for (RouteStep step : order.getStops())
		{
			patches += order.getPatches(step).size();
		}
		assertEquals(PatchLocation.values().length, patches);
	}

	@Test
	public void movingAStopChangesTheRoute()
	{
		RouteOrder order = RouteOrder.defaults();
		RouteStep second = order.getStops().get(1);
		RouteOrder moved = order.moveStop(second, -1);
		assertSame(second, moved.getStops().get(0));
		// Moving the first stop up does nothing.
		assertEquals(moved.getStops(), moved.moveStop(second, -1).getStops());

		List<RouteItem> items = Route.build(moved.sort(tasks()), Collections.emptyList(), moved);
		assertSame(second, items.get(0).getStep());
	}

	@Test
	public void savedNamesRoundTripAndUnknownNamesAreIgnored()
	{
		RouteOrder order = RouteOrder.defaults().moveStop(RouteStep.ANGLERS_RETREAT, -1);
		List<String> stops = new ArrayList<>(order.stopNames());
		stops.add("NOT_A_STOP");
		Map<String, List<String>> patches = new HashMap<>(order.patchNames());
		RouteOrder loaded = RouteOrder.fromNames(stops, patches);
		assertEquals(order.getStops(), loaded.getStops());

		// Nothing saved gives the defaults.
		assertEquals(RouteOrder.defaults().getStops(), RouteOrder.fromNames(null, null).getStops());
		// A partial save still has every stop; missing ones go in their built-in place.
		RouteOrder partial = RouteOrder.fromNames(Collections.singletonList("ANGLERS_RETREAT"), null);
		assertEquals(RouteStep.values().length, partial.getStops().size());
		assertSame(RouteStep.values()[0], partial.getStops().get(0));
	}

	@Test
	public void movingAPatchReordersItWithinItsStop()
	{
		RouteStep fossil = PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST.getStep();
		RouteOrder order = RouteOrder.defaults();
		List<PatchLocation> before = order.getPatches(fossil);
		assertTrue(before.size() > 1);
		PatchLocation last = before.get(before.size() - 1);
		RouteOrder moved = order.movePatch(last, -1);
		List<PatchLocation> after = moved.getPatches(fossil);
		assertEquals(last, after.get(after.size() - 2));

		List<RunTask> sorted = moved.sort(tasks());
		int a = -1;
		int b = -1;
		for (int i = 0; i < sorted.size(); i++)
		{
			if (sorted.get(i).getLocation() == last)
			{
				a = i;
			}
			if (sorted.get(i).getLocation() == before.get(before.size() - 2))
			{
				b = i;
			}
		}
		assertTrue(a < b);
	}

	// ---------------------------------------------------------------- RunNeeds

	private static RunNeeds.Line line(List<RunNeeds.Line> lines, CropType crop)
	{
		for (RunNeeds.Line l : lines)
		{
			if (l.getCrop() == crop)
			{
				return l;
			}
		}
		return null;
	}

	@Test
	public void needsCountWhatYouCarryAndSkipDonePatches()
	{
		List<RunTask> tasks = tasks();
		Set<String> done = new HashSet<>();
		int yews = 0;
		for (RunTask t : tasks)
		{
			if (t.getCrop() == CropType.YEW && t.isDue())
			{
				yews++;
			}
		}
		for (RunTask t : tasks)
		{
			if (t.getCrop() == CropType.YEW)
			{
				done.add(t.getKey());
				break;
			}
		}
		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(CropType.YEW.getSapling().getId(), 2);
		List<RunNeeds.Line> lines = RunNeeds.compute(tasks, done, id -> inv.getOrDefault(id, 0));
		RunNeeds.Line yew = line(lines, CropType.YEW);
		assertEquals(yews - 1, yew.getSaplings());
		assertEquals(2, yew.getSaplingsCarried());
		assertTrue(yew.isShort());
		assertTrue(RunNeeds.shortCount(lines) >= 1);
	}

	@Test
	public void carriedItemsAreSharedNotDoubleCounted()
	{
		// Calquat and magic both pay with coconuts in some setups; whatever shares an item must split it.
		List<RunTask> tasks = tasks();
		Map<Integer, Integer> inv = new HashMap<>();
		for (RunTask t : tasks)
		{
			if (t.getCrop().getPayment() != null)
			{
				inv.put(t.getCrop().getPayment().getId(), 1);
			}
		}
		List<RunNeeds.Line> lines = RunNeeds.compute(tasks, new HashSet<>(), id -> inv.getOrDefault(id, 0));
		Map<Integer, Integer> handedOut = new HashMap<>();
		for (RunNeeds.Line l : lines)
		{
			if (l.getCrop().getPayment() != null)
			{
				handedOut.merge(l.getCrop().getPayment().getId(), l.getPaymentCarried(), Integer::sum);
			}
		}
		for (int given : handedOut.values())
		{
			assertTrue(given <= 1);
		}
	}

	@Test
	public void nothingDueMeansNoLines()
	{
		List<RunTask> tasks = tasks();
		Set<String> done = new HashSet<>();
		for (RunTask t : tasks)
		{
			done.add(t.getKey());
		}
		assertTrue(RunNeeds.compute(tasks, done, id -> 0).isEmpty());
	}

	// ---------------------------------------------------------------- ActionMatcher

	@Test
	public void xpWithOnePatchChangeMatches()
	{
		List<ActionMatcher.Change> changes = Arrays.asList(
			new ActionMatcher.Change(100, "TREE_FALADOR#0"),
			new ActionMatcher.Change(90, "TREE_VARROCK#0"));
		assertEquals("TREE_FALADOR#0", ActionMatcher.find(101, changes, new HashSet<>()));
		assertNull(ActionMatcher.find(103, changes, new HashSet<>()));
	}

	@Test
	public void twoChangesAtOnceAreTooAmbiguous()
	{
		List<ActionMatcher.Change> changes = Arrays.asList(
			new ActionMatcher.Change(100, "east"),
			new ActionMatcher.Change(100, "west"));
		assertNull(ActionMatcher.find(100, changes, new HashSet<>()));
		// Unless one of them is already done.
		assertEquals("west", ActionMatcher.find(100, changes, new HashSet<>(Collections.singletonList("east"))));
	}
}

package com.treerunning.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class PatchMatcherTest
{
	private static final int FALADOR_REGION = 11828;
	private static final int FOSSIL_REGION = 14651;
	private static final int FARMING_GUILD_REGION = 4922;
	private static final int NOWHERE = 1;

	private static List<RunTask> tasks()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, CropType.YEW);
		crops.put(PatchType.FRUIT_TREE, CropType.PAPAYA);
		crops.put(PatchType.HARDWOOD, CropType.IRONWOOD);
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		PlanSettings s = new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), XpTable.xpForLevel(99), 1);
		return RunPlanner.buildTasks(s, 99, Collections.emptyMap(), 0);
	}

	@Test
	public void plantingOutOfOrderTicksThePatchYouAreAt()
	{
		// Route order starts at the Farming Guild, but you planted in Falador first.
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.TREE, FALADOR_REGION,
			Collections.singleton(PatchLocation.TREE_FALADOR));
		assertEquals(PatchLocation.TREE_FALADOR, m.getTask().getLocation());
		assertEquals(PatchMatcher.Confidence.PATCH, m.getConfidence());
	}

	@Test
	public void regionAloneIsEnoughWhenThereIsOnePatch()
	{
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.TREE, FALADOR_REGION, Collections.emptySet());
		assertEquals(PatchLocation.TREE_FALADOR, m.getTask().getLocation());
		assertEquals(PatchMatcher.Confidence.REGION, m.getConfidence());
	}

	@Test
	public void varbitTellsFossilIslandPatchesApart()
	{
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.HARDWOOD, FOSSIL_REGION,
			Collections.singleton(PatchLocation.HARDWOOD_FOSSIL_ISLAND_WEST));
		assertEquals(PatchLocation.HARDWOOD_FOSSIL_ISLAND_WEST, m.getTask().getLocation());
	}

	@Test
	public void sharedVarbitInAnotherRegionIsIgnored()
	{
		// 4771 is also Fossil Island east's varbit, but you're in Falador.
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.TREE, FALADOR_REGION,
			Collections.singleton(PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST));
		assertEquals(PatchLocation.TREE_FALADOR, m.getTask().getLocation());
	}

	@Test
	public void farmingGuildPatchesAreMatchedByType()
	{
		Set<PatchLocation> changed = EnumSet.of(PatchLocation.CELASTRUS_FARMING_GUILD);
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.CELASTRUS, FARMING_GUILD_REGION, changed);
		assertEquals(PatchLocation.CELASTRUS_FARMING_GUILD, m.getTask().getLocation());
	}

	@Test
	public void unknownPlaceFallsBackToRouteOrder()
	{
		PatchMatcher.Match m = PatchMatcher.match(tasks(), new HashSet<>(), PatchType.TREE, NOWHERE, Collections.emptySet());
		assertEquals(PatchLocation.TREE_FARMING_GUILD, m.getTask().getLocation());
		assertEquals(PatchMatcher.Confidence.ROUTE, m.getConfidence());
	}

	@Test
	public void alreadyTickedPatchIsSkipped()
	{
		Set<String> done = new HashSet<>();
		done.add(RunTask.keyFor(PatchLocation.TREE_FALADOR, 0));
		PatchMatcher.Match m = PatchMatcher.match(tasks(), done, PatchType.TREE, FALADOR_REGION, Collections.emptySet());
		// You're at Falador and Falador is done, so it must not tick some other tree patch far away.
		assertNull(m);
	}

	@Test
	public void nothingLeftReturnsNull()
	{
		Set<String> done = new HashSet<>();
		for (RunTask t : tasks())
		{
			if (t.getLocation().getPatchType() == PatchType.CALQUAT)
			{
				done.add(t.getKey());
			}
		}
		assertNull(PatchMatcher.match(tasks(), done, PatchType.CALQUAT, NOWHERE, Collections.emptySet()));
	}
}

package com.treerunning.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import com.treerunning.data.RouteStep;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PlannerTest
{
	private static final int LEVEL_89_XP = 4_842_295;
	private static final long NOW = 1_800_000_000_000L;

	private static PlanSettings settings(CropType tree, CropType fruit)
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, tree);
		crops.put(PatchType.FRUIT_TREE, fruit);
		crops.put(PatchType.HARDWOOD, CropType.IRONWOOD);
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		return new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), XpTable.xpForLevel(99), 1);
	}

	@Test
	public void xpTableMatchesKnownValues()
	{
		assertEquals(LEVEL_89_XP, XpTable.xpForLevel(89));
		assertEquals(5_346_332, XpTable.xpForLevel(90));
		assertEquals(13_034_431, XpTable.xpForLevel(99));
		assertEquals(89, XpTable.levelForXp(LEVEL_89_XP));
		assertEquals(89, XpTable.levelForXp(5_346_331));
		assertEquals(90, XpTable.levelForXp(5_346_332));
		assertEquals(99, XpTable.levelForXp(200_000_000));
	}

	@Test
	public void intervalsMatchGrowthTimes()
	{
		assertEquals(1, CropType.YEW.getIntervalRuns(1));
		assertEquals(1, CropType.CALQUAT.getIntervalRuns(1));
		assertEquals(4, CropType.IRONWOOD.getIntervalRuns(1));
		assertEquals(5, CropType.REDWOOD.getIntervalRuns(1));
		assertEquals(2, CropType.HESPORI.getIntervalRuns(1));
	}

	@Test
	public void yewPapayaAllPatchesTakesAbout45Runs()
	{
		XpProjection projection = XpProjection.toGoal(LEVEL_89_XP, settings(CropType.YEW, CropType.PAPAYA));
		assertTrue(projection.reachesGoal());
		// Five hardwood patches (Fossil Island x3, Locus Oasis, Anglers' Retreat).
		assertEquals(45, projection.getRuns());

		int runs = projection.getRuns();
		Map<CropType, Integer> plantings = projection.getPlantings();
		assertEquals(7 * runs, (int) plantings.get(CropType.YEW));
		assertEquals(7 * runs, (int) plantings.get(CropType.PAPAYA));
		assertEquals(3 * runs, (int) plantings.get(CropType.CALQUAT));
		assertEquals(runs, (int) plantings.get(CropType.CELASTRUS));
		assertEquals(5 * (int) Math.ceil(runs / 4.0), (int) plantings.get(CropType.IRONWOOD));
		assertEquals((int) Math.ceil(runs / 2.0), (int) plantings.get(CropType.HESPORI));
		// Redwood only starts once you hit 90.
		assertTrue(plantings.get(CropType.REDWOOD) < Math.ceil(runs / 5.0) + 1);
	}

	@Test
	public void fasterCropsTakeFewerRuns()
	{
		int magic = XpProjection.toGoal(LEVEL_89_XP, settings(CropType.MAGIC, CropType.DRAGONFRUIT)).getRuns();
		int yewPalm = XpProjection.toGoal(LEVEL_89_XP, settings(CropType.YEW, CropType.PALM)).getRuns();
		int yewPapaya = XpProjection.toGoal(LEVEL_89_XP, settings(CropType.YEW, CropType.PAPAYA)).getRuns();
		int maple = XpProjection.toGoal(LEVEL_89_XP, settings(CropType.MAPLE, CropType.PAPAYA)).getRuns();
		assertTrue(magic < yewPalm);
		assertTrue(yewPalm < yewPapaya);
		assertTrue(yewPapaya < maple);
	}

	@Test
	public void forRunsPlantsExactlyThatManyRuns()
	{
		XpProjection p = XpProjection.forRuns(LEVEL_89_XP, 10, settings(CropType.YEW, CropType.PAPAYA));
		assertEquals(10, p.getRuns());
		assertEquals(70, (int) p.getPlantings().get(CropType.YEW));
	}

	@Test
	public void runRateHelpers()
	{
		// Last four runs: 200, 200, 100, 200
		assertEquals(175.0, XpProjection.averageOfRecent(java.util.Arrays.asList(100, 100, 200, 200, 100, 200), 4), 0.001);
		assertEquals(0, XpProjection.runsAtRate(100, 100, 50));
		assertEquals(3, XpProjection.runsAtRate(0, 101, 50));
		assertEquals(-1, XpProjection.runsAtRate(0, 101, 0));
	}

	@Test
	public void growingHardwoodIsNotDue()
	{
		PlanSettings s = settings(CropType.YEW, CropType.PAPAYA);
		Map<String, Long> planted = new HashMap<>();
		planted.put(RunTask.keyFor(PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST, 0), NOW - 60 * 60_000L);
		List<RunTask> tasks = RunPlanner.buildTasks(s, 89, planted, NOW);

		RunTask fossil0 = find(tasks, PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST, 0);
		RunTask fossil1 = find(tasks, PatchLocation.HARDWOOD_FOSSIL_ISLAND_MIDDLE, 0);
		assertFalse(fossil0.isDue());
		assertTrue(fossil0.getNote().startsWith("Ready in"));
		assertTrue(fossil1.isDue());

		// Redwood needs 90.
		assertFalse(find(tasks, PatchLocation.REDWOOD_FARMING_GUILD, 0).isDue());
		// 25 patches, including Anglers' Retreat and three at Fossil Island.
		assertEquals(25, tasks.size());
		// Route order: Farming Guild first, Fossil Island last.
		assertEquals(RouteStep.FARMING_GUILD, tasks.get(0).getStep());
		assertEquals(RouteStep.FOSSIL_ISLAND, tasks.get(tasks.size() - 1).getStep());
	}


	@Test
	public void shortCropsAreTimedToo()
	{
		PlanSettings s = settings(CropType.YEW, CropType.PAPAYA);
		Map<String, Long> planted = new HashMap<>();
		String taiBwo = RunTask.keyFor(PatchLocation.CALQUAT_TAI_BWO_WANNAI, 0);
		String kastori = RunTask.keyFor(PatchLocation.CALQUAT_KASTORI, 0);
		// Calquat takes 21 h 20 m.
		planted.put(taiBwo, NOW - 18 * 3_600_000L);
		planted.put(kastori, NOW - 22 * 3_600_000L);
		List<RunTask> tasks = RunPlanner.buildTasks(s, 90, planted, NOW);
		assertFalse(find(tasks, PatchLocation.CALQUAT_TAI_BWO_WANNAI, 0).isDue());
		assertTrue(find(tasks, PatchLocation.CALQUAT_TAI_BWO_WANNAI, 0).getNote().startsWith("Ready in 3h"));
		assertTrue(find(tasks, PatchLocation.CALQUAT_KASTORI, 0).isDue());
		// Never timed: due.
		assertTrue(find(tasks, PatchLocation.CALQUAT_SUMMER_SHORE, 0).isDue());
	}

	@Test
	public void supplyLinesCombineSharedPayments()
	{
		Map<CropType, Integer> plantings = new EnumMap<>(CropType.class);
		plantings.put(CropType.MAGIC, 10);
		plantings.put(CropType.DRAGONFRUIT, 4);
		List<SupplyCalculator.SupplyLine> lines = SupplyCalculator.compute(plantings, id -> 5, id -> 100);

		SupplyCalculator.SupplyLine coconuts = lines.stream().filter(l -> l.getName().equals("Coconut")).findFirst().get();
		assertEquals(10 * 25 + 4 * 15, coconuts.getNeed());
		assertTrue(coconuts.isPayment());

		SupplyCalculator.SupplyLine magic = lines.stream().filter(l -> l.getName().equals("Magic")).findFirst().get();
		assertEquals(10, magic.getNeed());
		// seed + 2 seedling stages + sapling, 5 of each
		assertEquals(20, magic.getHave());
		assertEquals(0, magic.getShort());
		// Prices: the seed for crop rows, the item for payments.
		assertEquals(100, magic.getPriceEach());
		assertEquals((10 * 25 + 4 * 15 - 5) * 100L, coconuts.getShortCost());
	}

	@Test
	public void xpGoalPastNinetyNineKeepsGoing()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, CropType.YEW);
		PlanSettings s = new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), 50_000_000, 1);
		XpProjection p = XpProjection.toGoal(LEVEL_89_XP, s);
		assertTrue(p.reachesGoal());
		// 7 yews a run: (50M - 4.84M) / 50,056 per run.
		assertEquals((int) Math.ceil((50_000_000 - LEVEL_89_XP) / (7 * 7150.9)), p.getRuns());
	}

	private static RunTask find(List<RunTask> tasks, PatchLocation location, int index)
	{
		return tasks.stream().filter(t -> t.getLocation() == location && t.getIndex() == index).findFirst().get();
	}
}

package com.treerunning.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import com.treerunning.data.RouteStep;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class RouteTest
{
	private static List<RunTask> tasks(int level)
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, CropType.YEW);
		crops.put(PatchType.FRUIT_TREE, CropType.PAPAYA);
		crops.put(PatchType.HARDWOOD, CropType.IRONWOOD);
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);
		PlanSettings s = new PlanSettings(crops, EnumSet.allOf(PatchLocation.class), XpTable.xpForLevel(99), 1);
		return RunPlanner.buildTasks(s, level, Collections.emptyMap(), 0);
	}

	private static int indexOf(List<RouteItem> items, String key)
	{
		for (int i = 0; i < items.size(); i++)
		{
			if (items.get(i).getKey().equals(key))
			{
				return i;
			}
		}
		return -1;
	}

	@Test
	public void bankBeforeComesAheadOfThatStopsPatches()
	{
		BankStop before = new BankStop("a", RouteStep.CATHERBY, true, "Catherby bank");
		BankStop after = new BankStop("b", RouteStep.CATHERBY, false, "Catherby bank");
		List<RouteItem> items = Route.build(tasks(99), Arrays.asList(before, after));

		int patch = indexOf(items, RunTask.keyFor(PatchLocation.FRUIT_CATHERBY, 0));
		assertEquals(patch - 1, indexOf(items, "bank:a"));
		assertEquals(patch + 1, indexOf(items, "bank:b"));
		assertEquals(RouteStep.CATHERBY, items.get(patch - 1).getStep());
	}

	@Test
	public void nextIsTheBankBeforeAStopsPatches()
	{
		BankStop before = new BankStop("a", RouteStep.CATHERBY, true, "Catherby bank");
		List<RouteItem> items = Route.build(tasks(99), Collections.singletonList(before));
		Set<String> done = new HashSet<>();
		for (RouteItem item : items)
		{
			if (item.getStep().ordinal() < RouteStep.CATHERBY.ordinal())
			{
				done.add(item.getKey());
			}
		}
		RouteItem next = Route.next(items, done);
		assertTrue(next.isBank());
		assertEquals("Bank: Catherby bank", next.getBank().getLabel());

		done.add("bank:a");
		assertEquals(PatchLocation.FRUIT_CATHERBY, Route.next(items, done).getTask().getLocation());
	}

	@Test
	public void bankWithNothingLeftAfterItIsSkipped()
	{
		BankStop last = new BankStop("z", RouteStep.FOSSIL_ISLAND, false, "Bank chest");
		List<RouteItem> items = Route.build(tasks(99), Collections.singletonList(last));
		Set<String> done = new HashSet<>();
		for (RouteItem item : items)
		{
			if (!item.isBank())
			{
				done.add(item.getKey());
			}
		}
		assertNull(Route.next(items, done));
	}

	@Test
	public void levelLockedPatchesAreNotNext()
	{
		// At 89, redwood (90) is listed but not due.
		List<RouteItem> items = Route.build(tasks(89), Collections.emptyList());
		Set<String> done = new HashSet<>();
		done.add(RunTask.keyFor(PatchLocation.TREE_FARMING_GUILD, 0));
		done.add(RunTask.keyFor(PatchLocation.FRUIT_FARMING_GUILD, 0));
		done.add(RunTask.keyFor(PatchLocation.CELASTRUS_FARMING_GUILD, 0));
		RouteItem next = Route.next(items, done);
		assertEquals(PatchLocation.HESPORI_FARMING_GUILD, next.getTask().getLocation());
		assertFalse(items.get(indexOf(items, RunTask.keyFor(PatchLocation.REDWOOD_FARMING_GUILD, 0))).isDue());
	}

	@Test
	public void stepAfterSkipsFinishedStops()
	{
		List<RouteItem> items = Route.build(tasks(99), Collections.emptyList());
		RouteItem first = items.get(0);
		assertEquals(RouteStep.GNOME_STRONGHOLD, Route.stepAfter(items, first, new HashSet<>()));
	}

	@Test
	public void runNeedsCountsDuePatchesOnly()
	{
		List<RunNeeds.Line> needs = RunNeeds.compute(tasks(89));
		// Redwood needs 90, so it's not on the list at 89.
		for (RunNeeds.Line line : needs)
		{
			assertFalse(line.getCrop() == CropType.REDWOOD);
		}
		RunNeeds.Line yew = needs.get(0);
		assertEquals(CropType.YEW, yew.getCrop());
		assertEquals(7, yew.getSaplings());
		assertEquals(70, yew.getPayment());
		int total = RunNeeds.totalSaplings(needs);
		assertEquals(24, total);
		for (RunNeeds.Line line : needs)
		{
			if (line.getCrop() == CropType.HESPORI)
			{
				assertEquals(0, line.getPayment());
			}
		}
	}
}

package com.treerunning.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PatchStateTest
{
	@Test
	public void treeStatesComeFromRuneLitesTable()
	{
		// Oak: 8-11 growing, 12 check-health, 13 grown (chop down), 14 stump (RuneLite PatchImplementation).
		PatchReading growing = PatchKind.TREE.read(8);
		assertEquals(PatchCondition.GROWING, growing.getCondition());
		assertEquals("Oak", growing.getCrop());
		assertEquals(0, growing.getStage());
		assertEquals(PatchCondition.CHECK_HEALTH, PatchKind.TREE.read(12).getCondition());
		assertEquals(PatchCondition.GROWN, PatchKind.TREE.read(13).getCondition());
		assertEquals(PatchCondition.STUMP, PatchKind.TREE.read(14).getCondition());
		assertEquals(PatchCondition.EMPTY, PatchKind.TREE.read(0).getCondition());
		assertTrue(PatchKind.TREE.read(0).isWeeds());
	}

	@Test
	public void everyHerbGrowsInFourStagesOfTwentyMinutes()
	{
		boolean sawRanarr = false;
		for (int v = 0; v < 256; v++)
		{
			PatchReading r = PatchKind.HERB.read(v);
			if (r.getCondition() == PatchCondition.GROWING && "Ranarr".equals(r.getCrop()) && r.getStage() == 0)
			{
				sawRanarr = true;
				assertEquals(20, r.getMinutesPerStage());
				assertEquals(80, r.maxMinutesLeft());
				assertTrue(HerbType.byCropName(r.getCrop()) == HerbType.RANARR);
			}
		}
		assertTrue(sawRanarr);
	}

	@Test
	public void allotmentCropsAreNamedLikeOurTypes()
	{
		for (int v = 0; v < 256; v++)
		{
			PatchReading r = PatchKind.ALLOTMENT.read(v);
			if (r.getCondition() == PatchCondition.GROWING && !r.isWeeds())
			{
				assertTrue("unknown allotment crop " + r.getCrop(), AllotmentType.byCropName(r.getCrop()) != null);
			}
		}
	}

	@Test
	public void regionExceptionsMatchRuneLite()
	{
		// Catherby: the herb farm's varbits reach into the fruit tree's region, and vice versa.
		assertTrue(HerbLocation.CATHERBY.isAt(2813, 3463, 0));
		assertTrue(HerbLocation.CATHERBY.isAt(2830, 3445, 0));
		assertFalse(PatchLocation.FRUIT_CATHERBY.isAt(2830, 3445, 0));
		assertTrue(PatchLocation.FRUIT_CATHERBY.isAt(2860, 3433, 0));
		assertFalse(HerbLocation.CATHERBY.isAt(2860, 3433, 0));
		// Fossil Island hardwood only on the ground floor.
		assertTrue(PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST.isAt(3715, 3835, 0));
		assertFalse(PatchLocation.HARDWOOD_FOSSIL_ISLAND_EAST.isAt(3715, 3835, 1));
	}
}
